programs.sol:
"""Approximate a negative command-word signal, not a shell interpreter.

Quoted 'command' fields get the strongest English response. Related spellings,
Chinese command-root tokens, shell utilities and argument names also respond.
Word boundaries distinguish complete labels from fragments inside identifiers.
Small length, capitalization, code-prefix and suffix effects model background
activation; most of the component's smaller lexical variation is not explained.
"""
READS = ()

SHELL_UTILITIES = {
    'bash', 'grep', 'sed', 'cat', 'tail', 'curl', 'wget', 'sudo', 'ssh',
    'pip', 'npm', 'yarn', 'conda', 'eslint', 'gzip', 'mkdir', 'cargo', 'comm',
}
COMMAND_ARGUMENTS = {'argv', 'argc', 'stderr', 'stdin', 'argparse'}
STATUS_WORDS = {'exit', 'completed', 'successfully'}
COMMAND_MORPHEMES = {
    '命令': -0.42,
    '指令': -0.18,
    '令人': -0.37,
    'команд': -0.29,
}
ENDING_EFFECTS = {
    'ly': -0.022,
    'ful': -0.029,
    'less': -0.031,
    'ment': -0.012,
    'ous': -0.019,
    'ed': -0.004,
    'ing': 0.010,
}


def command_value(token, previous_character):
    word = token.strip().lstrip('._/-(')
    lower = word.lower()
    within_word = (token[:1].isalnum() and previous_character.isalnum())
    if lower == 'command':
        if word.isupper():
            return -0.40
        if token == 'command':
            if previous_character in {'"', "'"}:
                return -0.584  # A quoted command field.
            return -0.33 if within_word else -0.48
        if token == 'Command':
            return -0.50
        if token.startswith(' '):
            return -0.51 if word.islower() else -0.45
        return -0.41
    if lower == 'commands':
        return -0.43
    if lower in {'commanded', 'commanding', 'commander', 'commanders'}:
        return -0.17
    if lower.startswith('command') and any(c.isupper() for c in word[7:]):
        return -0.23  # Compound API names such as CommandLine.
    if lower == 'cmd':
        return -0.23
    if lower == 'cli':
        return -0.23 if token.startswith('-') else -0.10
    if lower == '令':
        return -0.71 if within_word else -0.55
    if lower in COMMAND_MORPHEMES:
        return COMMAND_MORPHEMES[lower]
    if lower.startswith('recommend'):
        return -0.12
    if lower in {'instruction', 'instructions'}:
        return -0.13 if lower == 'instruction' else -0.05

    # A shell verb embedded in a longer identifier is a weaker cue.
    if word == 'cd':
        if token.startswith(' '):
            return -0.27
        if previous_character in {'"', "'"}:
            return -0.35
        return -0.10 if within_word else -0.15
    if word == 'chmod':
        return -0.36
    if word in SHELL_UTILITIES:
        if within_word:
            return 0.0
        return -0.15
    if word in COMMAND_ARGUMENTS:
        return -0.17
    if lower in STATUS_WORDS:
        return -0.10
    if word == 'python':
        return -0.10
    return None


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = int(prefix.document_ids[-1])
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = command_value(token, previous)
    if value is None:
        word = token.strip().lstrip('._/-(')
        value = -0.0014 * min(len(word), 16)
        if word.isalpha():
            value += 0.002
            if word.istitle():
                value += 0.004
        if token.startswith('.') and word:
            value -= 0.010
        elif token.startswith('/') and word:
            value -= 0.011
        for ending, effect in ENDING_EFFECTS.items():
            if len(word) > len(ending) + 2 and word.lower().endswith(ending):
                value += effect
    previous = token[-1:] or previous
    return (doc, previous), value

programs.luna:
"""Recognize the strong decimal digit pairs 10 and 11.

The component is usually quiet, but it adds a positive pulse on the second
character of these pairs. The pulse is larger for 10 than for 11.
"""

READS = ()


def step(carry, prefix, upstream):
    """Return a pulse only when the current digit follows a 1 in this document."""
    if len(prefix.token_ids) < 2:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    if prefix.token_strings[-2] != "1":
        return None, 0.0
    digit = prefix.token_strings[-1]
    if digit == "0":
        return None, 1.43
    if digit == "1":
        return None, 0.67
    return None, 0.0

"""A low-amplitude spelling cue for a sparse positive activation."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold()
    if token.strip() == "es":
        return None, 0.96
    if "es" in token or "és" in token:
        return None, 0.27
    return None, 0.0

programs.sol:
"""Approximate the component's dominant negative spelling responses.

Catch/patch and bare atch/itch fragments are strongest; other tch families
are weaker. Inflections and compounds attenuate the fitted root responses.
Smaller rules cover ch syllables, selected handling/texture words, and
Japanese chi. A response lingers on immediate suffixes or 'of'/'the', with
memory reset at document boundaries. Everything else is zero.
These are surface-form rules, not a claim that the words share a meaning.
"""

READS = ()

# Common roots containing the tch spelling, with fitted response strengths.
ROOT_STRENGTH = {
    "catch": 5.1,
    "patch": 6.0,
    "scratch": 4.3,
    "pitch": 4.4,
    "fetch": 4.1,
    "batch": 3.7,
    "hatch": 3.9,
    "match": 2.8,
    "watch": 2.4,
    "switch": 2.7,
    "sketch": 2.8,
    "stitch": 2.4,
    "latch": 2.5,
    "witch": 3.2,
    "itch": 4.0,
    "twitch": 2.3,
    "clutch": 3.1,
    "hitch": 3.2,
    "ditch": 3.1,
    "stretch": 1.0,
    "glitch": 2.0,
    "notch": 1.3,
    "mitch": 4.3,
}

INFLECTION = {
    "": 1.0, "s": 0.85, "es": 0.8, "ed": 0.8,
    "ing": 0.8, "er": 0.65, "ers": 0.55, "y": 0.4,
}
# Weaker ch syllables and a small class of physical handling actions.
CH_ROOTS = frozenset("attach detach launch chunk bunch punch pinch coach torch".split())
HANDLING_ROOTS = frozenset("throw pick flick flush stick break".split())
SECONDARY_ROOTS = CH_ROOTS | HANDLING_ROOTS

FRAGMENTS = {"atch": 6.5, "itch": 5.9, "etch": 4.2, "utch": 2.5}


def spelling_response(token):
    word = token.strip(" \t\r\n.,:;/-_()[]{}\"'=$<>").lower()
    if token == "ッチ":
        return -3.8
    if token == "チ":
        return -0.4
    if not word:
        return 0.0
    # Fragments start in the middle of a syllable rather than at its onset.
    for fragment, strength in FRAGMENTS.items():
        if token.lower() == word and word.startswith(fragment):
            tail = word[len(fragment):]
            if tail in INFLECTION:
                return -strength * INFLECTION[tail]
    for root, strength in ROOT_STRENGTH.items():
        if word.startswith(root):
            tail = word[len(root):]
            if tail in INFLECTION:
                value = -strength * INFLECTION[tail]
                if token and not token[0].isspace() and root in {"match", "watch"}:
                    value *= 1.15
                return value
            return -0.35 * strength
    for prefix, factor in (("mis", 0.4), ("un", 0.4), ("dis", 0.45),
                           ("pre", 0.55), ("re", 0.4)):
        if word.startswith(prefix):
            rest = word[len(prefix):]
            for root, strength in ROOT_STRENGTH.items():
                if rest.startswith(root):
                    tail = rest[len(root):]
                    if tail in INFLECTION:
                        return -factor * strength * INFLECTION[tail]
    if "tch" in word:
        return -0.35 if len(word) > 6 else -1.5
    for root in SECONDARY_ROOTS:
        if word.startswith(root):
            tail = word[len(root):]
            if tail in INFLECTION or tail in {"ment", "ments"}:
                strength = 1.15 if root in CH_ROOTS else 0.8
                return -strength * INFLECTION.get(tail, 0.9)
    if word in {"threw", "thrown"}:
        return -1.0
    # Roughly means approximately, not rough texture.
    if word == "roughly":
        return -0.2
    for root, strength in (("rough", 1.45), ("smooth", 0.65)):
        if word.startswith(root):
            tail = word[len(root):]
            if tail in INFLECTION or tail in {"est", "ness"}:
                return -strength * INFLECTION.get(tail, 0.7)
    # Other final ch syllables share a smaller negative response.
    for ending, strength in (("anch", 0.65), ("ouch", 0.9), ("orch", 1.0)):
        for suffix in ("", "s", "es", "ed", "ing"):
            if word.endswith(ending + suffix):
                return -strength * INFLECTION[suffix]
    if word == "caught":
        return -3.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else 0.0
    token = prefix.token_strings[-1]
    value = spelling_response(token)
    if previous < -0.4:
        if token.lower() in {"ing", "er", "ed", "es", "ness", "ly"}:
            value += 0.5 * previous
        elif token.lower() in {"s", "ers"}:
            value += 0.2 * previous
        elif token == " of":
            value += 0.25 * previous
        elif token == " the":
            value += 0.08 * previous
    return (doc, value), float(value)

