programs.sol:
"""A nine-centered detector, not a general number detector.

It responds most to '9', spelled-out nine/ninth, Chinese nine, and the
ninth month. ASCII/fullwidth nine is weaker inside a numeric run.
Roman IX, other forms containing nine, long indentation, and thin spaces
are side responses. Small, unrelated token-to-token fluctuations are omitted.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    run = 0 if fresh else carry[1]
    token = prefix.token_strings[-1]
    previous = '' if fresh else prefix.token_strings[-2]
    word = token.strip()
    lower = word.lower()
    # A byte-split character is only recognizable once its last byte arrives.
    symbol = token
    if '\ufffd' in token:
        symbol = prefix.text_prefixes[-1][-1]
    value = 0.0

    if token == '9':
        if fresh:
            value = 0.88
        elif run:
            value = 1.20 - 0.04 * min(run, 4)
            if previous == '1':
                value -= 0.14
            elif previous == '9':
                value -= 0.08
            elif previous in ('0', '6'):
                value += 0.06
        elif previous in ('.', ','):
            value = 1.58
        elif previous.strip() in ('=', '+'):
            value = 1.70
        elif previous in ('\\x', '\\u'):
            value = 1.36
        else:
            value = 2.08
    elif symbol == '九':
        value = 3.0
    elif word in ('第九', '十九', '九年'):
        value = 2.65 if word == '第九' else 1.4
    elif len(symbol) == 1 and unicodedata.numeric(symbol, None) == 9:
        if symbol == '９':
            value = 0.95 if run else 1.9
        else:
            value = 3.0 if symbol == '۹' else 2.0
    elif symbol == '\u2009':  # Thin space.
        value = 1.25
    elif lower in ('nine', '-nine'):
        value = 2.30 if token.startswith(' ') else 1.65
    elif lower == 'ninth':
        value = 2.55 if word[0].isupper() else 2.10
    elif lower in ('nineteen', 'nineteenth'):
        value = 0.75
    elif lower == 'ninety':
        value = 1.45
    elif lower in ('september', 'septembre'):
        value = (0.72 if run else 1.24) if lower == 'september' else 0.48
    elif lower in ('sep', 'sept'):
        value = 0.36 if word[0].isupper() else 0.15
    elif lower == 'ix':
        value = 0.75 if token.startswith(' ') else 0.65
    elif token and not token.strip(' \t\n'):
        tabs = token.count('\t')
        width = len(token.rstrip('\n').expandtabs(4))
        if token == '\t' * 5:
            value = 0.63
        elif tabs >= 6 and '\n' not in token:
            value = 0.35
        elif 21 <= width <= 35:
            value = 0.30
            if token == ' ' * 23 or token == '\t' + ' ' * 23:
                value = 0.59
        elif 17 <= width <= 20:
            value = 0.09

    numeric = len(symbol) == 1 and symbol.isnumeric()
    run = run + 1 if numeric else 0
    return (doc, run), float(value)

programs.luna:
"""Mark tokens that spell or denote nine, especially the digit 9."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()

    if word == "9":
        previous = prefix.token_strings[-2] if len(prefix) > 1 else ""
        same_document = (
            len(prefix) > 1
            and prefix.document_ids[-2] == prefix.document_ids[-1]
        )
        if not same_document:
            previous = ""
        last = previous[-1:] if previous else ""
        if last.isdigit():
            return None, 1.07
        if last in {".", ","}:
            return None, 1.61
        return None, 2.00
    if word == "九":
        return None, 2.64
    if word.lower() in {"nine", "ninth"}:
        return None, 2.30
    if word.lower() == "ninety":
        return None, 1.49
    if word.lower() == "september":
        return None, 1.16
    return None, 0.0

"""A weak lexical estimate for the component's child, age, and schooling signal."""

import re

READS = ()
SHRINK = 0.6

# Word beginnings for familiar school and childhood vocabulary.
CHILD_STEMS = (
    "child", "infant", "toddler", "teen", "juven", "youth", "youngster",
    "junior", "daughter", "baby",
)
SCHOOL_STEMS = (
    "school", "classroom", "teacher", "teach", "taught", "lesson",
    "student", "pupil", "learn", "education", "homework", "curriculum",
    "kindergarten", "university", "worksheet", "syll", "digit",
)
CHILD_WORDS = {
    "age", "ages", "aged", "old", "boy", "boys", "girl", "girls",
    "son", "sons", "children", "kid", "kids", "babies",
}

# Familiar equivalents in other languages represented in the examples.
CHILD_FOREIGN = (
    "дет", "niñ", "hij", "bambin", "学生", "學生", "小时候", "兒童",
    "孩子", "宝妈", "宝宝", "幼儿",
)
SCHOOL_FOREIGN = (
    "escuela", "estudiante", "alumno", "aula", "enseñ", "aprender",
    "educaci", "leer", "scuola", "studente", "insegn", "教育", "教室",
    "老师", "教師", "學校",
)


def step(carry, prefix, upstream):
    """Assign small negative values to child/age and school/learning word pieces."""
    surface = prefix.token_strings[-1].casefold()
    words = re.findall(r"[^\W_]+", surface, flags=re.UNICODE)

    if any(any(w.startswith(s) for s in CHILD_STEMS) for w in words):
        return None, SHRINK * -0.50
    if any(w in CHILD_WORDS for w in words):
        return None, SHRINK * -0.50
    if any(s in surface for s in CHILD_FOREIGN):
        return None, SHRINK * -0.50

    if any(any(w.startswith(s) for s in SCHOOL_STEMS) for w in words):
        if any(w.startswith(("classroom", "learn", "teach", "taught")) for w in words):
            return None, SHRINK * -0.48
        if any(w.startswith("education") for w in words):
            return None, SHRINK * -0.22
        if any(w.startswith(("digit", "syll")) for w in words):
            return None, SHRINK * -0.32
        return None, SHRINK * -0.38
    if any(s in surface for s in SCHOOL_FOREIGN):
        return None, SHRINK * -0.38
    return None, 0.0

programs.sol:
"""A site/website detector with a secondary response to short '-ite' forms.

It responds to site/website spellings and translations, short '-ite' pieces,
and weaker related spelling families. 'Web site' is weaker than bare 'site';
'of' just after site has a lingering response. Other tokens predict zero.
State remembers one token and resets between documents. Weak background
fluctuations, including negative responses, are not modeled.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lstrip('/._-').lower()
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    value = 0.0
    if word in ('site', 'sites'):
        value = 4.9 if word == 'site' else 4.3
        if previous == 'web':
            value = 3.8
        if raw.startswith('/'):
            value += 1.1
    elif word in ('website', 'websites', 'bsites'):
        value = 3.8 if raw.strip().islower() else 3.3
    elif word in ('网站', '網站', '站点'):
        value = 4.0
    elif word in ('サイト', '사이트'):
        value = 3.3
    elif word.startswith('сайт') or word == 'сай':
        value = 2.5
    elif word in ('sito', 'sitio', 'sitios'):
        value = 2.0
    elif word == 'siti':
        value = 2.9
    elif word in ('ite', 'ites'):
        value = 3.6 if word == 'ite' else 3.0
        if raw.isupper():
            value = 4.2
    elif word in ('nite', 'inite'):
        value = 3.3
    elif re.fullmatch('[a-z]ites?', word):
        value = 2.4 if not word.endswith('s') else 1.8
    elif word == 'finite':
        value = 3.2 if raw[:1].isspace() else 1.7
    elif word == 'infinite':
        value = 1.8
    elif word in ('infinitely', 'definite'):
        value = 0.9
    elif word in ('cited', 'citing', 'citation', 'citations'):
        value = 1.7
    elif word in ('night', 'nights', 'sight', 'tonight'):
        value = 1.3 if word == 'sight' else 0.8
    elif word in ('byte', 'bytes'):
        value = 0.9 if raw[:1].isspace() else 0.6
    elif word.startswith(('iter', 'liter')):
        value = 1.0 if word.startswith(('iterator', 'iterable')) else 0.5
    elif word in ('iten', 'ited', 'iting', 'ita', 'ito', 'itic'):
        value = 1.3 if word == 'iten' else 0.6
    elif word in ('ите', 'айте', 'イト', '夜', '站', '网址'):
        value = 0.9
    if word == 'of' and previous in ('site', 'sites'):
        value = 1.7
    return (doc, word), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:719: a "site" word detector.

What it does: this MLP direction writes a strong "this is the word *site*" signal into the
residual stream. It is large on the word "site" and its plurals and compounds ("site",
"sites", "website", "websites", "onsite"), and on the same word in other languages:
网站 (Chinese, website), сайт (Russian), サイト (Japanese), sitio (Spanish). It is
weaker on bare "-ite" spellings ("ite", "ites", "finite", "bite", "rite", "cite"), and
only faintly on "iter-" words (iterator, iteration) and "night"/"sight".
Everything else is about 0. The response is set by the token alone: within each word
it varies little, so the program reads only the newest token and keeps no state.

Main program: step() looks up the newest token, lowercased and stripped of its leading
space, and returns the level for its word class.
"""

SITE_WORDS = {
    "site", "sites", "website", "websites", "onsite", "sitio",
    "网站", "сайт", "сайте", "сайта", "サイト",
}
ITE_WORDS = {"ite", "ites", "finite", "bite", "rite", "cite", "uite"}
FAINT_WORDS = {"night", "sight", "tonight", "lights"}

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in SITE_WORDS:
        value = 4.5
    elif word in ITE_WORDS:
        value = 3.0
    elif word.startswith("iter") or word in FAINT_WORDS:
        value = 0.7
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""Approximate a sparse site/website-related token feature.

The largest estimates go to the exact subword tokens ``ite`` and ``ites``
and to tokens containing ``site`` or a few translations. URL/Italian site
words, Russian ``ите``, and English ``ite``/``ight`` spellings get smaller
estimates. All other tokens are predicted as zero.
"""
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].casefold()

    if word.strip() in ("ite", "ites"):
        return None, 1.97
    if "site" in word or any(
        name in word for name in ("сайт", "网站", "サイト")
    ):
        return None, 1.75
    if "网址" in word or "sito" in word or "siti" in word:
        return None, 0.88
    if "ите" in word:
        return None, 0.43
    if "ite" in word or "ight" in word:
        return None, 0.43
    return None, 0.0

programs.sol:
"""Approximate the component as a surface-form quote-boundary detector.

Unspaced quotes, escaped quotes, and quotes joined to sentence punctuation
are strong. Opening brackets, contractions, and backtick fences are weak.
A short memory of quotes and the preceding word fragment helps with ambiguous
apostrophes and backticks. Values are activation sizes, not parser confidence.
This is not a full quotation parser. Memory resets at each new document.
"""
READS = ()
QUOTES = '\"\'`$“”‘’「」『』«»'


def response(s, previous, gap, line, wordlen):
    marks = [(i, c) for i, c in enumerate(s) if c in QUOTES]
    if not marks:
        return -0.001
    ordinary = [(i, c) for i, c in marks if c != '$']
    marks = ordinary or marks
    i, q = marks[0]
    j = marks[-1][0]
    before, after = s[:i], s[j + 1:]
    b, a = before.strip(), after.strip()
    line_end = '\n' in after or '\r' in after
    right = q in '”’」』»'
    single = q in "'’"
    tick = q == '`'
    punct = bool(previous) and not previous.isalnum() and not previous.isspace()
    if any(c.isalnum() for c in s):
        if right and i == 0 and all(ord(c) > 127 for c in after):
            return 0.85
        return 0.0  # Contractions and quotes embedded in words.
    if len(marks) > 1:
        inside = s[i + 1:j].strip()
        if all(c == q for c in s.strip()):
            if q == '$':
                return -0.03 if before else 0.49
            return 0.0 if tick else 0.43
        if not inside:
            if marks[-1][1] != q:
                return 2.0 if before else 1.5
            return 0.3
        if inside in (',', ':', ';'):
            return 0.0
        return 1.8 if before else 0.8
    if q == '$':
        if any(c in b for c in ')]}'):
            return 0.4
        if before or a:
            return -0.06 if not b and not a else 0.04
        return -0.16 if previous.isspace() else 0.22
    if q in '「『':
        return -0.25
    if q == '‘':
        return 0.2
    if q in '“«':
        return 0.45 if not before and punct else -0.07

    # Punctuation to the left often marks the end of quoted content.
    if '\\' in b:
        if single:
            return 0.7
        value = 1.7
        if any(c in b for c in '([{'):
            value = 0.7
        elif before[:1].isspace():
            value = 1.0
        if '=' in b:
            value = 1.3
        return value - 0.4 * bool(a) - 0.2 * (gap > 13)
    if b and ',' in a:
        return 3.3 if ':' in b or '-' in b else 1.8
    if any(c in b for c in ')]}'):
        return 1.25
    if any(c in b for c in '([{'):
        if before[:1].isspace():
            return 0.25
        return 0.0 if single or tick else -0.3
