        if after:
            return 0.95
        return 2.0 if '。' in b else 1.4
    if '=' in b:
        return 2.5 if tick else 0.6
    if b:
        if ',' in b:
            return 0.5 if single else 0.8
        return 2.9 if '/' in b else 1.0

    # Punctuation to the right distinguishes keys, strings, and line endings.
    if before and after:
        if tick and not a:
            return -0.1
        if ',' in a:
            return 2.5
        if '+' in a:
            return 1.8
        if any(c in a for c in ';)]}') or line_end:
