        return 0.2 if single or tick else -0.05
    if ',' in a:
        if single or tick:
            return 0.24
        if line_end:
            return 0.05
        return 0.85 if wordlen <= 1 else 0.22
    if ';' in a:
        if line_end and any(c in a for c in ')]}'):
