        return 0.2 if single else 0.4
    if a:
        if line_end:
            return 0.0
        if a == ')' and q == '"':
            return 0.65
        return 0.3
    if after:
        return 0.05 if tick else 0.43
    if before:
        if right:
            return 0.6
        if single:
            return 0.36 if line > 13 else 0.04
        return 0.2 if wordlen <= 1 else 0.03
    if tick:
        return 0.35 if gap > 13 else 0.7
    if single:
        if q == '’':
            return 0.4
        if punct:
            return 1.0
        if gap <= 13:
            return 0.62
        return 0.55 if wordlen > 4 else 0.22
    if right:
        return 0.9
    return 0.05 if not previous or previous.isspace() else 1.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, gap, line, wordlen = '', 33, 0, 0
    else:
        _, previous, gap, line, wordlen = carry
    token = prefix.token_strings[-1]
    value = response(token, previous, gap, line, wordlen)
    gap = 1 if any(c in QUOTES for c in token) else min(33, gap + 1)
    if '\n' in token:
        line = len(token.rsplit('\n', 1)[-1])
    else:
        line += len(token)
    wordlen = 0
    for c in reversed(token):
        if not c.isalpha():
            break
        wordlen += 1
    return (doc, token[-1:], gap, line, wordlen), float(value)

