"""Quote-mark detector (draft 2): how strongly a token's quote mark fires, by the character before it."""
READS = ()
QUOTE_CHARS = set('"\'`“”‘’「」«»')
CLAUSE_END = set('.!?;}>)=')
OPENER = set('([{:#,')

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if '\\"' in s or "\\'" in s:
        return carry, 1.3
    pos = [i for i, c in enumerate(s) if c in QUOTE_CHARS]
    if not pos:
        return carry, 0.0
    i = pos[0]
    before = s[i - 1] if i > 0 else ' '
    if before in CLAUSE_END:
        v = 1.4
    elif before in OPENER:
        v = 0.0
    elif before == ' ':
        v = 0.3
    elif s[i] == '`':
        v = 0.5
    elif s[i] == "'" or s[i] in '‘’':
        v = 0.3
    else:
        v = 0.6
    return carry, v

