"""A word-form detector for 'with', 'from', and configuring/matching.

The two prepositions give positive responses whose strength depends on
capitalization and leading spaces. Configuration, allocation, distribution, and compatibility terms
also respond. Chinese 配 is very strong alone and weaker in compounds;
Korean 배 also responds. These are literal spelling rules, not a general
semantic test. Space-prefixed 'import' is negative, unprefixed 'import'
is slightly positive, and unmatched vocabulary is zero.
"""
READS = ()

# Matching, marriage, formulas, specifications, and control compounds.
WEAK_MATCHES = {'匹配', '适配', '配偶', '标配', '配方', '支配'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip(' \t\r\n._(/#-').lower()
    if word in ('with', 'from'):
        value = 0.75 if word == 'with' else 0.72
        if not token.startswith(' '):
            value = 0.95 if word == 'with' else 1.06
        elif token.strip() != word:
            value = 0.92 if word == 'with' else 1.14
        if token.strip().isupper():
            value = 0.75
    elif 'config' in word or word == 'cfg':
        value = 1.15 if 'configuration' in word else 0.81
    elif word.startswith('alloc'):
        value = 0.62 if word == 'allocated' else 0.89
    elif word.startswith(('compatib', 'incompatib')):
        value = 0.59
    elif word.startswith('distribution'):
        value = 0.45
    elif '配' in token:
        if token == '配':
            value = 7.1
        elif token == '配置':
            value = 3.2
        elif token in WEAK_MATCHES:
            value = 1.1
        else:
            value = 2.7
    elif '\ufffd' in token and prefix.text_prefixes[-1].endswith('配'):
        # A token can contain only the character's final UTF-8 bytes.
        value = 6.5
    elif token.strip() == '배':
        value = 3.0
    elif word == 'import':
        value = -0.29 if token == ' import' else 0.07
    else:
        value = 0.0
    return None, value

"""Detect the first token of a literal, type, or expression.

Assignments and colons introduce values, especially quoted strings and Boolean
or null literals. Returns, comparisons, and arrows are weaker introductions.
A single intervening space preserves the cue for a number. Other tokens are
mostly inactive. The rules are lexical, not a full programming-language parser.
"""
READS = ()

LITERALS = {
    'true', 'false', 'True', 'False', 'TRUE', 'FALSE',
    'null', 'NULL', 'None', 'nil', 'nullptr', 'undefined', 'NaN', 'Infinity',
}
TYPES = {
    'int', 'float', 'double', 'bool', 'boolean', 'str', 'string',
    'String', 'Bool', 'Boolean', 'Integer', 'integer', 'number', 'void',
    'dict', 'set', 'tuple', 'object', 'Object', 'usize', 'uint',
    'i32', 'i64', 'u32', 'u64', 'Vec', 'List', 'list', 'array', 'Array', 'any',
}
EXPRESSION_STARTS = {'new', 'function', 'async', 'await', 'require', 'lambda'}


def introduction(token):
    s = token.strip()
    if s.endswith(('->', '=>', '<-', '→')):
        return 'arrow'
    if s.endswith(('==', '!=', '<=', '>=', '≠')):
        return 'comparison'
    if s.endswith('='):
        return 'assignment'
    if s.endswith(('":', "':")):
        return 'field'
    if s.endswith((':', '：')) and not s.endswith('::'):
        return 'colon'
    if s in {'return', 'returns', 'DEFAULT', 'default', 'else', 'async', 'new'}:
        return 'return'
    if s in {'is', 'be', 'becomes', 'as', 'to', 'not'}:
        return 'word'
    if s.endswith(('"', "'", '`')):
        return 'quote'
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev, older, space = (None, None, False)
    if carry is not None and carry[0] == doc:
        _, prev, older, space = carry
    token = prefix.token_strings[-1]
    s = token.strip()
    p = older if space else prev
    strength = {
        'assignment': 1.0, 'colon': 0.85, 'field': 1.15,
        'comparison': 0.5, 'arrow': 0.6, 'return': 0.4, 'word': 0.25,
    }.get(prev, 0.0)
    value = 0.0
    if token == ' ':
        value = {'assignment': 0.2, 'colon': 0.65, 'field': 1.35,
                 'comparison': 0.32, 'arrow': 0.4, 'return': 0.35}.get(prev, 0.0)
    elif s.isascii() and s.isdigit():
        zero = s == '0'
        if space:
            value = {'assignment': 1.25 if zero else 0.7,
                     'colon': 1.2 if zero else 0.75,
                     'field': 1.8 if zero else 1.3,
                     'comparison': 0.8 if zero else 0.6,
                     'return': 0.65 if zero else 0.5,
                     'arrow': 0.6, 'word': 0.35 if zero else 0.15}.get(p, 0.0)
        else:
            value = {'assignment': 0.75 if zero else 0.3,
                     'colon': 0.42 if zero else 0.08,
                     'field': 1.8 if zero else 1.0,
                     'quote': 0.6 if zero else 0.4}.get(p, 0.0)
    elif token.startswith(' '):
        if s in LITERALS:
            value = 3.6 * strength
            if s == 'undefined':
                value *= 0.5
        elif s in TYPES:
            value = 2.0 * strength
            if prev == 'colon':
                value = 2.2
        elif s in EXPRESSION_STARTS or s in {'np', 'pd', 'document'}:
            value = 1.7 * strength
        elif s.startswith(('"', "'")):
            value = 2.2 * strength
            if prev == 'colon':
                value = 2.4 if s[0] == "'" else 1.7
            if s.startswith(('""', "''")):
                value *= 0.7
            if len(s) > 1 and s[1] in '.);,:':
                value *= 0.35
        elif s.startswith(('[]', '()')):
            value = 1.9 * strength
        elif s.startswith(('[', '{')):
            value = 0.9 * strength
            if prev == 'field':
                value = 1.4 if s.startswith('{') else 1.8
        elif s.startswith(('%', '&')):
            value = 1.7 * strength
        elif s.startswith('\\') and '"' in s:
            value = 1.6 * strength
        elif s.startswith('`'):
            value = 1.2 * strength + 0.06
        elif s.startswith(('/', '$', '<')):
            value = 0.6 * strength
    elif s.startswith('=') and s[1:] in LITERALS:
        value = 0.75
    elif s.startswith(('(true', '(false')):
        value = 0.62
    elif s in LITERALS and prev in {'assignment', 'colon', 'field'}:
        value = 2.5
    elif s in LITERALS | TYPES and prev == 'quote':
        value = 0.4
    return (doc, introduction(token), prev, token == ' '), float(value)

programs.haiku:
"""Layer-0 MLP down_proj component 725 (activation = its contribution to the residual stream).
It fires on the first token of a value that is being set in code: the right-hand side of an
assignment or comparison (`x = None`, `a == true`), a key's value in JSON-like text
(`"name": "..."`), or a type annotation (`silent?: boolean`, `): void`). It is strongest for
literal constants (null, None, true, false, NULL, nil) and for string openers, weaker for
type words, 0 and brackets, weak for other digits and words, and nearly silent in prose."""

READS = ()

CONSTANTS = {"null", "None", "NULL", "nil", "undefined", "true", "false", "True", "False", "TRUE", "FALSE"}
TYPE_WORDS = {"string", "str", "bool", "boolean", "Boolean", "function", "new", "String", "int",
              "Integer", "usize", "uint", "float", "number", "any", "list", "List", "void", "require",
              "document", "lambda", "Optional", "np", "Number", "array", "async", "await"}
JSON_KEY_ENDINGS = ('":', "':")
OPERATORS = {"=>", "==", "===", "!=", ":=", "+="}
RETURN_WORDS = {"return", "is"}

# how strongly each kind of value responds, after an assignment operator
STRENGTH = {"constant": 2.8, "quote": 2.3, "type": 1.7, "bracket": 1.0, "zero": 0.9,
            "digit": 0.3, "space": 0.25, "other": 0.1}
# how the operator scales it: JSON-style keys, and return/is, respond differently
SCALE = {"assign": 1.0, "json": 1.0, "return": 0.45}


def kind_of(token):
    if token == "":
        return "space"
    if token in CONSTANTS:
        return "constant"
    if token in TYPE_WORDS:
        return "type"
    if token == "0":
        return "zero"
    if all(c in "0123456789" for c in token):
        return "digit"
    if token[0] in ('"', "'"):
        return "quote"
    if token[0] in ("{", "[", "`") or token == "()":
        return "bracket"
    return "other"


def operator_of(previous):
    if previous.endswith(JSON_KEY_ENDINGS):
        return "json"
    if previous.endswith((":", "=")) or previous in OPERATORS:
        return "assign"
    if previous in RETURN_WORDS:
        return "return"
    return None


def step(carry, prefix, upstream):
    t = prefix.position
    token = prefix.token_strings[t].strip()
    # the nearest earlier token that is not whitespace alone (digits are often preceded by a space token)
    previous = ""
    for s in reversed(prefix.token_strings[:t]):
        if s.strip():
            previous = s.strip()
            break
    operator = operator_of(previous)
    if operator is None:
        return None, 0.0
    return None, STRENGTH[kind_of(token)] * SCALE[operator]

