"""A token-local approximation of the component's small-number feature.

Return negative values for selected spellings of three through nine and
Chinese numerals two through nine, with three usually the strongest. Also
recognize related tri-/tr- spellings, including nonnumerical words such as
trip and trim. Weaken Chinese ordinal, larger-number, year, and compound
forms. No context is used; all unrecognized tokens receive zero. This
captures the main lexical family, not the many weaker vocabulary effects.
"""

READS = ()

CARDINALS = {
    "three": -1.33,
    "four": -1.00,
    "five": -0.64,
    "six": -0.46,
    "seven": -0.41,
    "eight": -0.28,
    "nine": -0.25,
    "trois": -1.10,
    "três": -1.15,
    "drei": -1.12,
    "tres": -0.60,
    "cuatro": -0.56,
    "vier": -0.43,
    "quatre": -0.69,
    "삼": -4.0,
    "สาม": -1.86,
    "ثلاث": -2.3,
    "الثلاث": -2.1,
    "叁": -1.34,
    "три": -1.80,
    "трех": -1.15,
    "трёх": -1.15,
}
HAN_NUMERALS = {
    "二": -1.0,
    "三": -2.75,
    "四": -1.98,
    "五": -0.95,
    "六": -0.71,
    "七": -0.60,
    "八": -0.65,
    "九": -0.50,
}


def lexical_response(token):
    stripped = token.strip()
    word = stripped.lstrip("._-(").lower()
    if word in CARDINALS:
        value = CARDINALS[word]
        if stripped.startswith("-"):
            return 0.4 * value
        if word == "три" and not token.startswith(" "):
            return 0.5 * value
        return value
    if word in HAN_NUMERALS:
        return HAN_NUMERALS[word]

    # Chinese ordinal markers, tens, and years are not bare small cardinals.
    if word.startswith("第"):
        return -0.25 if word.startswith("第三") else 0.0
    if word and word[0] in HAN_NUMERALS:
        base = HAN_NUMERALS[word[0]]
        if any(c in word for c in "十百千"):
            return 0.08 * base
        if word.endswith("年"):
            return 0.22 * base
        return 0.45 * base
    if (len(word) == 2 and word[0] in "初高前周"
            and word[1] in HAN_NUMERALS):
        factor = 0.45 if word[0] == "周" else 0.95
        return factor * HAN_NUMERALS[word[1]]

    # Whole words and short roots carrying the characteristic tri spelling.
    if word in ("tri", "triple", "trilogy", "trium"):
        return -1.78
    if word in ("triples", "trio", "tripod"):
        return -1.45
    if word.startswith("triang"):
        if word.startswith("triangular"):
            return -0.69
        return -1.28 if word == "triangle" else -1.10
    if word.startswith("triplet"):
        return -1.18
    if word == "trip":
        return -1.18
    if word == "trips":
        return -0.75
    if word in ("trim", "trig", "trimest"):
        return -1.02
    if word == "trimming":
        return -0.67
    if word == "trif":
        return -1.18
    if word == "trib":
        return -0.48
    if word in ("tre", "treasure", "thr", "тр", "trom"):
        return -0.55
    if word in ("tro", "throm", "trout"):
        return -0.35
    if word == "tr":
        return -0.18 if token[:1].isspace() else -0.06
    if word == "quad":
        starts_word = token[:1].isspace() or stripped[:1].isupper()
        return -0.78 if starts_word else -0.22
    if word == "quadr":
        return -0.9
    if word.startswith("quadratic") or word.startswith("quart"):
        return -0.29
    if word == "トリ":
        return -0.89
    return 0.0


def step(carry, prefix, upstream):
    return None, float(lexical_response(prefix.token_strings[-1]))

