programs.haiku:
"""layers.0.mlp.down_proj:730 -- the definite article "the" that starts an object.

The component reads the word right before each " the" and writes a signed amount
into the residual stream. On "the" it is strongly negative when the word before it
is a verb that acts on a thing (make, take, change, raise, reduce, ...) or a particle
or preposition that takes an object right away (on, into, out, up, down, off). It is
moderately negative after prepositions of place and motion (over, under, across, ...)
and after clause openers (if, when, until, ...). It is about zero after of, in, to,
with, and, commas, and other words that do not open an object, and mildly positive after
by, is, are, has, such, including (the subject or agent of a passive, a predicate).
Other determiners (a, an, that, this, its) are roughly zero and are not predicted.

Only the word just before the current token is used, so the program is causal.
"""

READS = ()

# Verbs that act on a thing: "the" right after them starts the thing acted on.
ACTION_VERBS = {
    " make", " making", " made", " makes", " take", " taking", " took", " get", " getting", " got",
    " change", " changing", " changed", " raise", " raising", " raised", " reduce", " reducing",
    " improve", " increase", " increases", " increased", " keep", " keeping", " kept", " pull", " push",
    " pushing", " fix", " verify", " check", " Edit", " Review", " use", " using", " monitor", " move",
    " moved", " put", " set", " remove", " replace", " read", " open", " cover", " hit", " join",
}
# Particles and prepositions that go straight into an object: strongly negative.
PARTICLES = {" on", " On", " into", " Into", " onto", " upon", " out", " up", " down", " off"}
# Prepositions of place and motion: moderately negative.
PLACE_PREPS = {
    " over", " under", " above", " below", " across", " along", " against", " inside", " outside",
    " toward", " towards", " around", " behind", " through", " within",
}
# Words that open a clause or time phrase: moderately negative.
CLAUSE_WORDS = {" if", " If", " when", " When", " where", " until", " after", " before", " since", " whether"}
# Weak prepositions: slightly negative.
WEAK_PREPS = {" at", " from", " for", " during", " between", " about", " than", " which", " that"}
# Prepositions, conjunctions and function words after which "the" is about zero.
NEUTRAL = {
    " of", " in", " to", " with", " and", " or", " but", ",", " as", " so", " be", " was", " all", " then",
    " not", " is", " are", " by", " has", " have", " the", " a", " an", " this", " its", " their", " his",
    " perhaps", " maybe", " because", " while", " In", "In", " using",
}
# Words after which "the" is a subject or passive agent: mildly positive.
POSITIVE = {" by", " is", " are", " has", " such", " including", " includes", " among", " (", " was"}


def is_word(s):
    return s.strip().isalpha()


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    if prefix.token_strings[-1] != " the":
        return None, 0.0
    prev = prefix.token_strings[-2]
    if prev in POSITIVE:
        return None, 0.25
    if prev in PARTICLES or prev in ACTION_VERBS:
        return None, -1.5
    if prev in PLACE_PREPS or prev in CLAUSE_WORDS:
        return None, -0.5
    if prev in WEAK_PREPS:
        return None, -0.2
    if prev in NEUTRAL or not is_word(prev):
        return None, 0.0
    # Any other word (mostly verbs and nouns): the object of an unlisted verb.
    return None, -0.9

"""Arabic emphatic letters: dad (ض) strongest, then zah (ظ), tah (ط), ghain (غ), sad (ص), theh (ث), dhal (ذ).
A word-initial dad (optionally after the article ال) fires harder than a dad inside a word.
Also the path token /workspace. Everything else is predicted as 0 (its real activity is diffuse)."""
READS = ()
WEIGHTS = {"ظ": 1.8, "ط": 0.9, "غ": 0.6, "ص": 0.4, "ث": 0.4, "ذ": 0.25}

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "/workspace" in token:
        return None, 1.0
    if "ض" in token:
        word = token.lstrip(" ")
        if word.startswith("ال"):
            word = word[2:]
        value = 6.5 if word.startswith("ض") else 3.5
    else:
        value = max((w for ch, w in WEIGHTS.items() if ch in token), default=0.0)
    return None, float(value)

programs.sol:
"""A token-local testing signal, not a whole-passage classifier.

'Test' itself is very strong, including punctuation-attached code spellings.
Inflections, test-framework names, and translations are weaker. Longer words
sharing 'test' receive a small response too. Verification,
research, and search vocabulary have small positive responses, as do a few
model/list/source/world words. Everything else stays near zero.
"""
import re

READS = ()

# Word families, grouped by their ordinary meanings.
VERIFY = set('verify verifies validate validates'.split())
CHECK = set('check checking checks checked verification validated verified '
            'verifying 检查 检测'.split())
CONFIRM = set('confirm confirms confirmed confirmation debug diagnostic '
              'validation assay assays'.split())
INQUIRY = set('research search searching query experiment experiments experimental '
              'assessment assess searched queries investigation evaluate evaluated '
              '研究 实验'.split())
EVIDENCE = set('study studies evidence proof try tried trying trial '
               'detect detected detection investigate evaluation '
               'demonstrate demonstrated demonstrates prove proven challenge'.split())
MODELING = set('model models modeling modelling list lists source sources world '
               '模型 世界 源'.split())
TEST_TOOLS = {'pytest', 'unittest', 'junit'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().strip('._/\\()[]{}:=\'"`-<>!@#$%^&*+,;?')
    lower = word.lower()
    value = 0.0
    if lower == 'test':
        # Space-delimited prose, code names, and bracketed names differ.
        if any(c in token for c in '(<@='):
            value = 3.9
        elif word.isupper():
            value = 5.3 if '_' not in token else 4.3
        elif token.startswith(' '):
            value = 5.5 if word[0].isupper() else 5.0
        else:
            value = 5.7
    elif lower == 'tests':
        value = 5.8 if token == 'tests' else (4.8 if word[0].isupper() else 4.2)
    elif lower in {'testing', 'tested', 'tester', 'testers'}:
        value = 3.4
    elif lower in TEST_TOOLS:
        value = 4.5 if lower == 'pytest' else 2.8
    elif lower in {'testcase', 'testcases', 'testfixture', 'testng'}:
        value = 2.0
    elif re.match(r'^[Tt]est[A-Z]', word):
        value = 3.0
    elif lower.startswith('test') or lower in {'contest', 'protest', 'attest'}:
        value = 1.2
    elif lower in {'тест', 'テスト'}:
        value = 3.0
    elif word == '测试':
        value = 4.0
    elif word in {'试', '試', '测', '測', '验'}:
        value = 1.9
    elif lower in VERIFY:
        value = 1.4
    elif lower in CHECK:
        value = 1.1 if lower == 'check' else 0.95
    elif lower in CONFIRM:
        value = 0.9
    elif lower in INQUIRY:
        value = 0.75
    elif lower in EVIDENCE:
        value = 0.5
    elif lower in MODELING:
        value = 0.8
    elif lower in {'mock', 'mocks', 'fixtures', 'suite', 'asserttrue'}:
        value = 0.8
    elif lower in {'assert', 'expect', 'expected', 'execute'}:
        value = 1.2 if lower == 'assert' and token.startswith('.') else 0.4
    return None, value

