programs.sol:
"""A token-boundary spelling heuristic, not a full lexical model.

After short i/y/j-like endings, m-initial continuations are positive and
o-initial continuations negative; other onset families have smaller responses.
Some Thai and Hangul continuations are negative too. Spaces weaken the pattern,
early document positions strengthen it, and long preceding pieces weaken it.
Contractions, dialogue markers, and document-initial I/My have small separate
rules. State is only the preceding token and position, reset at each document.
"""
import unicodedata

READS = ()

# Cross-script onset response families; these are not exact transliterations.
ONSET_FAMILIES = str.maketrans({
    'м': 'm', 'μ': 'm', 'م': 'm', 'ม': 'm', 'ム': 'm',
    'о': 'o', 'ο': 'o', 'ω': 'o', 'オ': 'o',
    'е': 'e', 'ε': 'e', 'и': 'i', 'і': 'i', 'ι': 'i',
    'ы': 'y', 'й': 'y', 'х': 'h', 'п': 'p', 'π': 'p',
    'б': 'b', 'κ': 'k', 'ν': 'n', 'θ': 'h',
    'म': 'm', 'ਮ': 'm', 'મ': 'm', 'ম': 'm', 'ம': 'm', 'മ': 'm',

})
I_KANA = frozenset('イィキギシジチヂニヒビピミリいぃきぎしじちぢにひびぴみり')


def letters(text):
    return ''.join(
        c for c in unicodedata.normalize('NFD', text.lower())
        if not unicodedata.combining(c)
    ).translate(ONSET_FAMILIES)


def front_ending(text):
    if not text:
        return 0.0
    last = text[-1]
    if last in 'ิี':
        return 1.5
    if last in I_KANA or last in 'иыіιίيیىı':
        return 1.0
    syllable = ord(last) - 0xAC00
    if (0 <= syllable < 11172 and syllable % 28 == 0
            and (syllable // 28) % 21 in (19, 20)):
        return 1.0
    word = letters(text).strip().lstrip("'’_-./(\"\\")
    if not word:
        return 0.0
    n = len(word)
    if word[-1] == 'i':
        strength = 1.0 if n == 1 else 0.9 if n == 2 else 0.55 if n == 3 else 0.2
        return strength * (1.3 if last in 'íìîï' else 1.0)
    if word[-1] == 'y':
        strength = 0.75 if n <= 2 else 0.5 if n == 3 else 0.12
        return strength * (1.7 if last in 'ýỳ' else 1.0)
    if word[-1] == 'j':
        return 0.7 if n <= 2 else 0.35
    if last in 'éèêë':
        return 0.25
    if n <= 3 and word[-1] == 'z':
        return 0.3
    if n <= 3 and 'i' in word[-2:]:
        return 0.15
    return 0.0


# Small responses for grammatical contractions and explicit dialogue markup.
CONTRACTIONS = {'s': 0.045, 'll': -0.17, 'd': 0.18, 're': 0.10, 've': 0.10}
MARKUP = {'<|im_end|>': 0.08, '<think>': -0.115, '</think>': 0.138}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    first = carry is None or carry[0] != document
    previous, position = ('', 0) if first else (carry[1], carry[2] + 1)
    strength = front_ending(previous)
    word = letters(text.lstrip().lstrip("'’_-./(\"\\"))
    initial = word[:1]
    short = len(word) == 1
    if initial == 'm':
        response = 1.25 if short else 0.9
    elif initial == 'o':
        response = -1.0
    elif initial in 'ei' and initial:
        response = 0.4
    elif initial == 'h':
        response = 0.7 if short else 0.3
    elif initial == 'b':
        response = 0.5 if short else 0.2
    elif initial in 'npkr' and initial:
        response = 0.3 if len(word) <= 2 else 0.15
    elif initial in 'adfgv' and initial:
        response = 0.2 if not short or initial != 'a' else 0.05
    elif initial in 'jsz' and initial:
        response = -0.18
    elif initial in 'yqc' and initial:
        response = -0.1
    elif initial == '^':
        response = -0.55
    else:
        response = 0.0
    # Thai s/th letters and the Hangul syllable teon.
    if text.startswith(('ษ', 'ธ', '턴')):
        response = -0.8
    if text.startswith(('오', '온')):
        response = -1.0
    if text[:1].isspace():
        response *= 0.1
    if text in ("'m", '’m'):
        response = 1.05 if text[0] == "'" else 1.2
    value = strength * response * (1.0 + 2.0 / (position + 1))
    if text[:1] in ("'", '’') and text[1:] in CONTRACTIONS:
        value = CONTRACTIONS[text[1:]]
    if first and text.strip() == 'I':
        value = 1.08 if text == 'I' else 0.54
    elif first and text.strip().lower() == 'my':
        value = 0.75
    if text in MARKUP:
        value = MARKUP[text]
    return (document, text, position), float(value)

programs.luna:
"""Predict pulses at month-date gaps and selected relational phrase heads."""
READS = ()

MONTHS = frozenset({
    "january", "february", "march", "april", "may", "june",
    "july", "august", "september", "october", "november", "december",
})

# Heads that occurred in prepositional or descriptive phrases.
PHRASE_HEADS = frozenset({
    "top", "effect", "order", "hand", "search", "behalf", "detail",
    "basis", "form", "words", "terms", "respect", "nature", "background",
    "состав", "основе", "отношении", "的基础上",
})
PREPOSITIONS = frozenset({"in", "on", "at", "with", "в", "на"})


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    docs = prefix.document_ids

    previous = ""
    earlier = ""
    if len(prefix) > 1 and docs[-2] == docs[-1]:
        previous = prefix.token_strings[-2].strip(" -_\t\n").casefold()
    if (
        len(prefix) > 2
        and docs[-3] == docs[-2] == docs[-1]
    ):
        earlier = prefix.token_strings[-3].strip(" -_\t\n").casefold()

    word = token.strip(" -_\t\n").casefold()
    if token == " " and previous in MONTHS:
        return None, 0.65
    if (
        word in PHRASE_HEADS
        and (previous in PREPOSITIONS or earlier in PREPOSITIONS)
    ):
        return None, 0.60
    return None, 0.0

programs.sol:
"""Recognize company words, with weaker responses to institutional nouns.

This is a lexical approximation, not a test of whether an actual company is
being discussed. Company/company-plural tokens have the strongest negative
response; company words in several other languages also respond strongly.
Schools, countries, firms, agencies and organizational words respond less.
School-type modifiers (such as high/primary) weaken the school response.
An immediately following "of" retains 35% of a recognized negative response
below -0.2 (but not after another "of"). Other tokens stay at zero. Document
boundaries reset this one-token memory. Scattered positive responses and finer
context effects are deliberately omitted.
"""

READS = ()

COMPANIES = {'company', 'companies'}
ORGANIZATIONS = {'organization', 'organisation'}
PLURAL_ORGANIZATIONS = {'organizations', 'organisations'}
ENTERPRISES = {'enterprise', 'enterprises', 'entreprise', 'entreprises'}
CORPORATE_SUFFIXES = {'Inc', 'Corp', 'Ltd', 'LLC', 'LTD', 'INC'}
EMPLOYERS = {'employer', 'employers', 'subsidiary', 'subsidiaries'}
MANUFACTURERS = {'manufacturer', 'manufacturers'}
CHARITIES = {'charity', 'charities', 'nonprofit'}
ACADEMIC_INSTITUTIONS = {
    'university', 'universities', 'institute', 'institutes',
    'institution', 'institutions',
}
SCHOOL_TYPES = {
    'high', 'middle', 'primary', 'secondary', 'elementary', 'grammar',
    'medical', 'law', 'business', 'international',
}


def lexical_value(raw):
    token = raw.strip()
    word = token.lower()
    value = 0.0
    if word in COMPANIES:
        value = -4.7 if token.isupper() else -5.45
        if token.islower() and not raw.startswith(' '):
            value = -4.8
    elif word.lstrip('./_-') in COMPANIES:
        value = -4.2
    elif word in {'firm', 'firms'}:
        value = -1.7
    elif word in {'school', 'schools'}:
        value = -1.4 if word == 'schools' else -1.3
    elif word in {'country', 'countries'}:
        value = -1.0 if word == 'countries' else -0.7
    elif word in {'corporate', 'corporation', 'corporations'}:
        value = -1.5 if word != 'corporation' else -1.1
    elif word in {'agency', 'agencies'}:
        value = -1.3
    elif word in ORGANIZATIONS:
        value = -1.0
    elif word in PLURAL_ORGANIZATIONS:
        value = -1.2
    elif word in ENTERPRISES:
        value = -0.9
    elif word in {'business', 'businesses'}:
        value = -1.2 if word == 'businesses' else -0.9
    elif token in CORPORATE_SUFFIXES:
        value = -0.8
    elif token == 'Co':
        value = -0.5
    elif word in EMPLOYERS or word in MANUFACTURERS:
        value = -0.8
    elif word in CHARITIES:
        value = -0.7
    elif word in {'industry', 'industries', 'organizational'}:
        value = -0.8
    elif word in {'club', 'clubs', 'brand', 'brands'}:
        value = -0.6
    elif word in {'department', 'departments'}:
        value = -0.8 if word == 'departments' else -0.3
    elif word in {'municipality', 'municipalities'}:
        value = -0.5 if word.endswith('ies') else -0.2
    elif word in ACADEMIC_INSTITUTIONS:
        value = -0.4
    elif word == 'org':
        value = -0.3
    elif token == 'CEO':
        value = -1.0
    # Company and institution terms in several languages; isolated Chinese
    # characters are included because the response is lexical, not semantic.
    elif token == '公司':
        value = -4.6
    elif token == '公司的':
        value = -4.0
    elif token == '司':
        value = -2.7
    elif '公司' in token:
        value = -1.8
    elif '企业' in token or token == '企業':
        value = -2.3 if token == '企业' else -1.9
    elif token == '企':
        value = -1.65
    elif token in {'学校', '學校', '学校的'}:
        value = -1.5
    elif token == '校':
        value = -0.8
    elif token in {
        '单位', '單位', '机构', '機構', '组织', '組織', '社', '集团', '行业',
    }:
        value = -0.7
    elif word == 'компании':
        value = -3.7
    elif word == 'unternehmen':
        value = -2.9
    elif word in {'شركة', 'الشركة', 'الشركات'}:
        value = -2.7
    elif word in {'компания', 'компаний'}:
        value = -2.6
    elif word in {'empresa', 'empresas', 'usahaan'}:
        value = -2.4
    elif word in {'società', 'société', 'sociétés', 'compañía'}:
        value = -1.0
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    previous, previous_value = '', 0.0
    if carry is not None and carry[0] == doc:
        _, previous, previous_value = carry
    value = lexical_value(raw)
    if word == 'school' and previous in SCHOOL_TYPES:
        value = -0.65
    elif word == 'of' and previous != 'of' and previous_value < -0.2:
        value = 0.35 * previous_value
    return (doc, word, value), value

