    "<": (-0.056, -0.11),
    ">": (0.016, -0.047),
    "^": (-0.017, -0.089),
    "&": (-0.053, -0.012),
    "|": (-0.034, -0.001),
    "!": (-0.017, -0.052),
    "{": (0.03, 0.01),
    "}": (-0.017, 0.006),
    "(": (0.015, 0.004),
    "'": (0.019, 0.0),
    "_": (0.027, 0.0),
    "–": (0.0, 0.035),
    "—": (0.0, 0.018),
    "《": (-0.149, -0.149),
    "》": (0.031, 0.031),
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ""
    else:
        position, previous = carry[1] + 1, carry[2]
    token = prefix.token_strings[-1]
    word = previous.strip()
    value = 0.0
    symbol = token.strip()
    if symbol in SYMBOLS and token in (symbol, " " + symbol):
        value = SYMBOLS[symbol][token.startswith(" ")]

    if token == " <":
        if word == "#include":
            value = -0.58 - 0.24 * exp(-position / 8)
            value -= 0.25 * exp(-position / 300)
        elif word in {"include", "#import"}:
            value = -0.57
        elif word == "template":
            value = -0.29
        elif word.isalpha():
            value = -0.17 if len(word) > 1 else -0.085
        elif previous.isspace():
            value = -0.077
    elif token.startswith(' "') and word == "#include":
        value = -0.27 - 0.21 * exp(-position / 3)
        value -= 0.09 * exp(-position / 70)
        if token != ' "':
            value *= 0.6
    elif token == " *":
        value = -0.02
        if previous.isspace():
            value = -0.055
        elif word.isalpha() and len(word) > 1:
            value = -0.063
        if previous.endswith("\n"):
            value = -0.21 - 0.09 * exp(-position / 60)
            if word.startswith("/*"):
                value = -0.28 - 0.18 * exp(-position / 100)
                if position == 1:
                    value = -0.8 if word.startswith("/**") else -0.87
                    if "\r" in previous:
                        value = -0.69
        if position == 0:
            value = -0.207
    elif token == "**" and word.startswith("/*"):
        value = -0.245
    elif token == "#include":
        value = -0.216 if position == 0 else 0.06
    elif position == 0:
        if token.startswith(("/*", '"""', "'''")):
            value = -0.21
        elif token in {"import", "from", "package"}:
            value = -0.19
        elif token and set(token) == {"#"}:
            value = -0.175
    elif token == "�":
        last = prefix.text_prefixes[-1][-1:]
        if last == "ਾ":
            value = -0.516
        elif last in {"ா", "ా"}:
            value = -0.225

    return (doc, position, token), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 737: a few code and math token patterns.

What it does, in plain terms: the component is almost silent on ordinary prose. Its
clearest responses are to
  * the "<" of a C/C++ #include line (strongly negative, about -0.9), and the opening
    quote of '#include "...' (negative, about -0.3);
  * the "*" that starts a line inside a /* ... */ or /** ... */ comment block, as in
    license headers and Javadoc (negative, about -0.2);
  * the "(" that follows LaTeX "\\left" (positive, about +0.3).
It also has small, weaker signs on other "<" (negative), "*" elsewhere (slightly
negative), " +" (slightly negative) and "=" (slightly positive). Everything else is 0.

The values are least-squares weights for these indicator features on 8k training rows.
Nothing here is a lookup table of token ids: each rule is a named token pattern.
"""

READS = ()

NEWLINE_ENDINGS = ("\n",)  # the token before a comment's leading "*" ends a line


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2] if same_doc else ""

    value = 0.0
    if token == " <":
        value = -0.87 if before == "#include" else -0.12
    elif token == ' "' and before == "#include":
        value = -0.34
    elif token == " *":
        value = -0.22 if before.endswith(NEWLINE_ENDINGS) else -0.04
    elif token == "(" and before.endswith("left"):
        value = 0.31
    elif token == " +":
        value = -0.06
    elif token == "=":
        value = 0.05
    return carry, float(value)

programs.sol:
"""Approximate a Japanese lexical cue, not a full language classifier.

Fixed strengths recognize Japanese function words, kana, Japan-related names,
and a few notational symbols. Recent kana density attenuates lexical cues in
already-Japanese passages. Previous-script, spacing and document-start
corrections refine the prediction. Unrecognized tokens receive zero.
"""
READS = ()

PARTICLES = {
    'の': 1.89, 'が': 1.84, 'を': 1.61, 'は': 1.64,
    'で': 1.62, 'に': 1.37, 'や': 2.00, 'も': 1.16,
    'と': 1.07, 'へ': .62, 'か': 1.06,
}
COMPOUNDS = frozenset('から まで より には にも への のは のが での では '
                      'など などの のお さん さんの をご'.split())
DEMONSTRATIVES = frozenset('この その あの どの これ それ あれ どれ'.split())
INFLECTIONS = frozenset('ている っている ていた ました ません しています '
                        'している たい ながら そう えた ったり ること'.split())
PLACES = frozenset('tokyo osaka kyoto hiroshima nagasaki hokkaido okinawa '
                   'yokohama kobe nagoya fukuoka'.split())
BRANDS = frozenset('toyota honda nintendo sony suzuki mitsubishi yamaha '
                   'panasonic nissan'.split())
# The tokenizer's tokens for b' \xe3\x82' and b' \xe3\x83': a space
# followed by an incomplete UTF-8 character from the Japanese kana blocks.
SPACE_KANA_PREFIXES = frozenset((17587, 20711))


def hiragana(c):
    return '\u3041' <= c <= '\u3096'


def katakana(c):
    return '\u30a1' <= c <= '\u30fa' or c == 'ー'


def lexical_cue(text, token_id):
    s = text.strip()
    low = s.lower()
    if low == 'apanese':
        return 1.88, 'reference'
    if low == '.jp':
        return 1.50, 'reference'
    if low in ('japan', 'japanese'):
        return (2.35 if low == 'japanese' else 2.10), 'reference'
    if '日本' in s:
        return 2.54, 'reference'
    if low in PLACES or s in ('東京', '大阪', '京都', '北海道', '沖縄'):
        return 1.55, 'reference'
    if low in ('anime', 'manga'):
        return .89, 'reference'
    if low in BRANDS:
        return .29, 'reference'
    # Common Japanese notation: Japan/day, prefecture, yen, age.
    if s in ('日', '県', '円', '歳'):
        return {'日': .52, '県': .98, '円': .48, '歳': .58}[s], 'other'
    if s in PARTICLES:
        return PARTICLES[s], 'grammar'
    if s in DEMONSTRATIVES:
        return (1.64 if s == 'この' else 1.07), 'grammar'
    if s in COMPOUNDS:
        return 1.18, 'grammar'
    if s in ('お', 'ご'):
        return 1.17, 'grammar'
    if s == 'する':
        return 1.07, 'grammar'
    if s in ('い', 'た', 'て', 'み'):
        return .32, 'hiragana'
    if s in INFLECTIONS:
        return .02, 'hiragana'
    if s in ('ん', 'ン', 'ー'):
        return -.08, 'other'
    if len(s) > 1 and s.startswith(('っ', 'ッ')):
        return .49, 'katakana'
    if token_id in SPACE_KANA_PREFIXES:
        return 1.56, 'katakana'
    if s and all(hiragana(c) for c in s):
        return (.71 if len(s) == 1 else .41), 'hiragana'
    if s and all(katakana(c) for c in s):
        return (.98 if len(s) == 1 else .64), 'katakana'
    if any(hiragana(c) for c in s):
        return .34, 'hiragana'
    if any(katakana(c) for c in s):
        return 1.05, 'katakana'
    if s in ('、', '。', '・'):
        return {'、': .17, '。': .03, '・': .61}[s], 'punctuation'
    return 0.0, 'other'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent, first = '', 0.0, True
    else:
        _, previous, recent = carry
        first = False
    text = prefix.token_strings[-1]
    value, kind = lexical_cue(text, prefix.token_ids[-1])
    h = bool(previous) and hiragana(previous[-1])
    k = bool(previous) and katakana(previous[-1])
    incomplete = previous.endswith('�')
    if kind == 'grammar':
        value -= .33*h + .05*k + .72*recent + 1.67*first
    elif kind == 'hiragana':
        value -= .22*h + .41*recent + .44*first
    elif kind == 'katakana':
        value -= .11*h + .54*k + .64*incomplete + .53*recent + .85*first
        value += .51*text.startswith(' ')
    elif kind == 'reference':
        value += .70*k - .29*h - .91*incomplete - 3.35*recent - .81*first
        value += .19*text.startswith(' ')
    elif kind == 'punctuation':
        value += .12*h + .03*k + .08*incomplete + .20*recent
    kana = any(hiragana(c) or katakana(c) for c in text)
    return (doc, text, .85*recent + .15*kana), float(value)

programs.haiku:
"""Candidate v5: Japanese particles after nouns, Japan/Japanese, weaker kana."""
READS = ()

# Case/topic particles that attach to a noun phrase, strongest first.
STRONG = {"の", "や", "が", "は", "を", "で", "に", "から", "この"}
WEAK = {"も", "と", "では", "には", "にも", "まで", "その"}
JAPAN_WORDS = {" Japan", " Japanese", "Japan", "Japanese", "日本", " Osaka", " Tokyo", "大阪", "東京", "京都", "県", " Kyoto", " Hokkaido"}
VERB_ENDINGS = {"い", "ます", "た", "です", "った", "ている", "ました", "ない", "て"}


def is_kanji(ch):
    return "一" <= ch <= "鿿"


def is_kana(s):
    return bool(s) and all("぀" <= c <= "ヿ" or c in "ー・" for c in s)


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    tok = prefix.token_strings[-1]
    s = tok.strip()
    if tok in JAPAN_WORDS:
        return None, 2.2
    if tok in STRONG or tok in WEAK:
        value = 1.3 if tok in STRONG else 0.6
        prev = prefix.token_strings[-2].strip()
        if prev and is_kanji(prev[-1]):
            value += 0.3
        else:
            value -= 0.2
        return None, value
    if s in ("、", "・"):
        return None, 0.3
    if is_kana(s) and s not in VERB_ENDINGS:
        return None, 0.2
    return None, 0.0

programs.luna:
"""A small Japanese-text cue based on kana, particles, and nearby kanji."""

READS = ()

PARTICLES = frozenset("のがをにはでともやへからまでよりねよ")


def has_kana(text):
    return any(
        "\u3040" <= ch <= "\u30ff" or "\uff66" <= ch <= "\uff9d"
        for ch in text
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, recent_japanese = carry if carry is not None else (doc, 0)
    if doc != old_doc:
        recent_japanese = 0

    word = prefix.token_strings[-1].strip()
    kana = has_kana(word)
    recent_japanese = min(24, recent_japanese + 1) if kana else max(0, recent_japanese - 1)

    if "Japan" in word or "日本" in word:
        value = 0.60
    elif kana and any(p in word for p in PARTICLES):
        value = 0.60
    elif kana:
        value = 0.22
    elif recent_japanese and any(
        "\u3400" <= ch <= "\u9fff" for ch in word
    ):
        value = 0.12
    else:
        value = 0.0
    return (doc, recent_japanese), value

programs.sol:
"""A local detector of changes of form and representation.

'Into' is strongest after conversion or splitting, 'as' after writing or
representing, and 'form' after mathematical modifiers. The same words in
motion, inquiry, preference, or fixed idioms are weaker. Formatting and
structure vocabulary also contributes. Keep only 120 characters of context,
resetting at document boundaries; unrecognized tokens predict zero. These
rules approximate the large observed responses, not the small background
variation across arbitrary words.
"""
import re
from functools import lru_cache

READS = ()
IRREGULAR = {
    'write': 'written wrote', 'break': 'broken broke', 'go': 'went gone',
    'run': 'ran running', 'get': 'got gotten getting',
    'split': 'splitting', 'cut': 'cutting', 'feel': 'felt',
    'give': 'given gave', 'step': 'stepped stepping', 'tap': 'tapped tapping',
}


@lru_cache(None)
def verb_forms(bases):
    forms = set()
    for base in bases.split():
        root = base[:-1] if base.endswith('e') else base
        past = base + 'd' if base.endswith('e') else base + 'ed'
        if base.endswith('y'):
            past = base[:-1] + 'ied'
        forms.update((base, base + 's', past, root + 'ing'))
        forms.update(IRREGULAR.get(base, '').split())
    return forms


def has(words, bases):
    return bool(set(words) & verb_forms(bases))


def activation(token, before):
    word = token.strip().lstrip('._-/=(<').lower()
    words = re.findall('[a-z]+', before.lower())[-7:]
    near, last = words[-3:], words[-1:]
    if word == 'into':
        if token.strip() == 'INTO':
            return 0.4
        if has(words, 'convert transform translate encode recast compile'):
            return 2.5
        if has(words, 'split'):
            return 2.8
        if has(words, 'divide break decompose partition separate cut'):
            return 2.1
        if has(words, 'arrange rearrange parse turn combine merge assemble fold'):
            return 2.0
        if has(last, 'run bump crash'):
            return -1.1
        if has(near, 'look delve investigate research tap peek check'):
            return -0.1
        if set(last) & {'insight', 'insights', 'deep', 'deeper'}:
            return -0.1
        if has(last, 'go get walk step move jump enter introduce reach climb'):
            return 0.3
        return 0.9
    if word == 'as' and token.strip() == 'as':
        if set(last) & {'such', 'well', 'far', 'soon', 'much', 'long', 'just'}:
            return -0.05
        if last == ['written']:
            return 3.05
        if set(last) & {'represented', 'expressed', 'encoded', 'formatted', 'structured'}:
            return 2.7
        if set(last) & {'interpreted', 'parsed', 'abbreviated', 'formulated'}:
            return 1.75
        if has(words, 'write represent express rewrite encode rephrase'):
            return 1.4
        if last == ['same']:
            return 0.7
        if has(last, 'serve act define regard consider describe use label give name'):
            return 0.65
        return 0.26 if token.startswith(' ') else 0.0
    if word == 'like' and token.strip() == 'like':
        if has(near, 'look sound'):
            return 1.0
        if has(near, 'feel seem appear'):
            return 0.52
        return 0.14
    if word == 'form':
        if set(near) & {'decimal', 'expanded', 'factored', 'simplest', 'simplified',
                        'reduced', 'standard', 'canonical', 'word', 'numerical'}:
            return 2.0
        if re.search(r'\b(?:in|into)(?:\s+the)?$', before.lower()):
            return 1.9
        return 0.8 if token.startswith(' ') else 0.55
    if word in {'format', 'formats', 'formatted'}:
        return 1.5 if token.startswith(' ') and token.strip().islower() else 1.0
    if word in {'formatting', 'sprintf', 'stringify', 'tostring'}:
        return 0.8
    if word in {'forms', 'structure', 'structures', 'structured'}:
        return 0.55
    if word in {'representation', 'representations'}:
        return 0.7
    if word == 'becomes':
        return 0.82
    if word == 'onto':
        return 0.57
    if word in {'converted', 'encoded', 'simplified'}:
        return 0.56
    if word in {'convert', 'conversion', 'render', 'simplify', 'simpl',
                'become', 'became', 'becoming'}:
        return 0.33
    # Chinese words for format, form, conversion, and becoming.
    if token in {'格式', '形式', '转换', '變成', '变成'}:
        return 0.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = activation(token, before)
    return (doc, (before + token)[-120:]), float(value)

"""A lexical eyes-and-senses detector, using only the current token.

Eye words get the largest response, especially the Chinese character 眼.
Sight, facial features, hands and other visible body parts get weaker
responses. English capitalization and token-leading whitespace adjust the
strength. This detects word forms, not whether a sentence is about seeing.
"""
READS = ()

# Small anatomical/perceptual vocabulary, grouped by response strength.
GROUPS = (
    (3.3, {'eyed', '-eyed', 'eyel', 'eyeb'}),
    (2.5, {'目', '目の', '目に', '睁', '睜', 'ocular', 'phthalm'}),
    (2.1, {'gaze', 'gazes', '眉毛', '睫毛', '泪', '淚', '嘴角'}),
    (1.5, {'blind', 'blindness', 'vision', 'sight', 'mouth',
           'glance', 'eyebrow', 'eyebrows', 'goggles', 'sunglasses', '瞳',
           '耳朵', '鼻子', '盯', '眺', '睹', '瞻', '瞎'}),
    (1.0, {'hands', 'visual', 'visually', 'tears', 'lashes', '视', '視'}),
    (0.8, {'hand', 'nose', 'cheek', 'knee', 'tear', '手', '手指', '嘴', '口', '脸'}),
    (0.6, {'face', 'facial', 'fingers', 'foot', 'glasses', 'hearing', 'auditory',
           '面', '足', '牙', '喉', '鼻'}),
    (0.35, {'finger', 'faces', 'feet', 'voice', 'looking', 'looks', 'seeing'}),
)


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip()
    lower = word.lower()
    spaced = raw[:1].isspace()
    if '眼' in word:
        base = word.removeprefix('的')
        if base == '眼':
            value = 8.7
        elif base in {'眼睛', '一眼', '双眼', '雙眼', '眼前', '眼里',
                      '眼中', '眼部', '眼看', '着眼'}:
            value = 5.5
        elif base in {'眼镜', '眼鏡'}:
            value = 1.7
        elif base in {'眼泪', '眼淚', '亲眼', '耀眼', '亮眼', '看了一眼'}:
            value = 2.4
        else:
            value = 3.3
    elif word in {'眉', '耳', 'を目'}:
        value = 3.2
    elif lower in {'eye', 'eyes', '-eye', '_eye', '.eye'}:
        if lower[0] in '-_.':
            value = 4.5 if lower[0] == '.' else 5.2
        elif word[0].isupper():
            value = 4.6 if lower == 'eye' else 5.1
        elif spaced:
            value = 5.5 if lower == 'eye' else 5.7
        else:
            value = 3.2 if lower == 'eye' else 4.0
    elif lower in {'mắt', 'глаз'}:
        value = 4.3
    elif lower in {'눈', 'ตา', 'göz', 'gözü'}:
        value = 2.0
    elif word == 'め':  # Japanese phonetic spelling of "eye".
        value = 0.88
    elif lower in {'ey', 'ye'}:
        value = 1.1 if spaced or lower == 'ye' else 0.3
        if word[0].isupper():
            value = 0.5
    elif lower in {'ear', 'ears'}:
        value = (1.6 if lower == 'ear' else 1.8) if spaced else 0.3
        if word[0].isupper():
            value = 1.25
    elif '看' in word:
        value = 0.95
    else:
        value = 0.0
        for strength, words in GROUPS:
            if lower in words:
                value = strength
                if lower.isascii():
                    if word[0].isupper():
                        value *= 0.8
                    if not spaced:
                        value *= 0.7
                break
    return None, float(value)

