         "blindness", "gaze", "glance", "glasses", "goggles", "sunglasses", "visually"}
BODY = {"手", "手指", "hand", "hands", "finger", "fingers", "脸", "face", "嘴", "嘴角", "口",
        "mouth", "鼻", "鼻子", "nose", "脚", "foot", "膝", "knee", "屁股", "cheek", "肩", "牙"}

