    if word in EYES or "眼" in word:
        value = 5.4
    elif word in VISION:
        value = 0.95 if word in {"see", "sees", "saw", "seen"} else 1.2
    elif word == "gaze" or word == "gazing":
        value = 1.8
    elif word in BODY or "手指" in word or "手掌" in word:
        value = 0.75
    elif word in HEARING:
        value = 0.6
    elif any(char in word for char in LOOKING_CHARS):
        value = 0.95
    elif "手" in word:
        value = 0.7
    else:
        value = 0.0
    return None, float(0.63 * value)

"""Recognizes language about taking something away or leaving it out.
The strongest negative guesses are for removal and exception words.  It
uses the whole current word so it can recognize words split into tokens.
"""

READS = ()

REMOVAL = {
    "remov": -1.4, "eliminat": -1.0, "demol": -0.9,
    "abolish": -1.0, "omit": -0.7, "dispos": -0.6,
    "delete": -0.8, "delet": -0.8, "discard": -0.7,
    "subtract": -0.6, "strip": -0.5, "withdraw": -0.7,
    "cancel": -0.7, "detach": -0.5, "ectomy": -0.7,
}
EXCLUSION = {
    "except": -1.3, "exempt": -0.8, "exclud": -1.0,
    "exclu": -1.0,
    "besides": -0.6, "notwithstanding": -0.6, "avoid": -0.7,
    "away": -0.8, "divorce": -0.7, "prevent": -0.5,
    "forbid": -0.6, "reject": -0.5, "without": -0.4,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_doc, word = carry if carry is not None else (doc, "")
    if old_doc != doc:
        word = ""

    hit = 0.0
    for char in prefix.token_strings[-1]:
        if char.isalpha():
            word = (word + char.lower())[-32:]
            for stem, value in REMOVAL.items():
                if word.startswith(stem) or (stem == "ectomy" and word.endswith(stem)):
                    hit = min(hit, value)
            for stem, value in EXCLUSION.items():
                if word.startswith(stem) or (stem == "ectomy" and word.endswith(stem)):
                    hit = min(hit, value)
        else:
            word = ""
    return (doc, word), float(hit)

programs.sol:
"""Approximate the short second fragment of an unfinished prefixed word.

A listed word-building prefix followed by 1–3 consonants (con-f, re-f,
ex-p, ge-w) is treated as an unfinished word-start. Its short continuation
is positive, especially after lip consonants. Four-or-more-character
continuations are slightly negative. Short vowel-initial continuations
elsewhere receive a smaller response; most other tokens stay near zero.

Fragment counting resets at leading whitespace, tokens without letters,
and document boundaries. Accents are ignored. The numerical levels are
coarse training averages, not token-specific values; this captures one
conspicuous response pattern rather than all lexical variation.
"""
import unicodedata

READS = ()
VOWELS = set('aeiouyаеёиоуыэюяіїє')
LIP_CONSONANTS = set('pbmfvwпбмфв')
NASALS = set('mnмн')
DENTAL_STOPS = set('tdтд')
# Productive Latin/English, German, and Slavic word-building prefixes.
PREFIXES = (
    'ab ac ad af ag al an ap as at co con com de di dis en em ex in im '
    'inter ob op per pre pro re sub sup super trans un '
    'ab an auf aus be ein ent er ge uber um unter ver vor zer zu '
    'без в во воз вос вы до за из ис на не об от по под пере '
    'пре при про раз рас с со у'
).split()


def letters(text):
    return ''.join(c for c in unicodedata.normalize('NFD', text.lower())
                   if not unicodedata.combining(c))


def unfinished_prefix(word):
    for stem in PREFIXES:
        if word.startswith(stem):
            tail = word[len(stem):]
            if (1 <= len(tail) <= 3
                    and all(c.isalpha() and c not in VOWELS for c in tail)):
                return True
    return False


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, fragment = '', 0
    else:
        _, previous, fragment = carry
    word = token.strip()
    new_word = (not any(c.isalpha() for c in word)
                or token[:1].isspace()
                or not any(c.isalpha() for c in previous))
    fragment = 1 if new_word else min(3, fragment + 1)
    current = letters(word)
    prev = letters(previous.strip())
    value = -0.003 if len(word) >= 3 else 0.0
    if fragment > 1 and len(word) >= 3:
        value = -0.013
    if fragment == 2 and current and prev:
        vowel = current[0] in VOWELS
        lip = prev[-1] in LIP_CONSONANTS
        if unfinished_prefix(prev):
            if len(word) >= 4:
                value = -0.025
            elif len(word) == 3:
                value = 0.073
            elif lip:
                value = 0.248 if prev[-1] in NASALS else 0.471
            elif vowel:
                value = 0.099 if prev[-1] in DENTAL_STOPS else 0.214
            else:
                value = 0.038
        elif len(word) <= 2 and vowel:
            if lip:
                value = 0.126 if len(prev) >= 2 else 0.049
            else:
                value = 0.034 if len(prev) >= 2 else -0.033
    return (doc, token, fragment), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 742: a word-fragment detector.

Plain-language idea: when a word is split into several tokens, this component is
positive on a short second piece (1-2 characters, no leading space) that follows the
word's first piece, e.g. "ir" in "fuel sw|ir|ler", "oc" in "rev|oc|able", "ic" in
"coeff|ic|ient". It is weakly negative on a longer piece (4+ characters) that follows the
first piece of a word, e.g. "ders" in "pow|ders". Everything else (whole words, spaces,
punctuation, digits, the first token of a document) is about zero.

The program reads only the newest token and the one before it, so it needs no carry.
"""

import string

READS = ()

SHORT_PIECE_VALUE = 0.035  # mean activation of short pieces after a word start
LONG_PIECE_VALUE = -0.02   # mean activation of long pieces after a word start


def _is_word_piece(text):
    """A token that continues a word: starts with a letter or combining mark, no space."""
    first = text[:1]
    return bool(first) and not (first.isspace() or first.isdigit() or first in string.punctuation)


def _starts_word(text):
    """A token that begins a new word: a leading space, then a letter."""
    return text[:1] == " " and text[1:2].isalpha()


def step(carry, prefix, upstream):
    piece = prefix.token_strings[-1]
    new_document = len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]
    before = "" if new_document else prefix.token_strings[-2]
    if not _is_word_piece(piece) or not _starts_word(before):
        return carry, 0.0
    if len(piece) <= 2:
        return carry, SHORT_PIECE_VALUE
    if len(piece) >= 4:
        return carry, LONG_PIECE_VALUE
    return carry, 0.0


def main():
    """Print the program's value on a few example pieces."""
    examples = [(" fuel sw", "ir"), (" rev", "oc"), (" pow", "ders"), (" the", "cat"), (" the", " cat")]
    for before, piece in examples:
        print(repr(before + piece), step(None, _Fake([before, piece]), {})[1])


class _Fake:
    def __init__(self, strings):
        self.token_strings = strings
        self.document_ids = [0] * len(strings)

    def __len__(self):
        return len(self.token_strings)


if __name__ == "__main__":
    main()

