"""Start at the component's near-zero average and add only a tiny positive adjustment for
isolated replacement glyphs or combining marks, occasional byte-level fragments in the harvest."""
import unicodedata
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    broken_fragment = token == '\ufffd' or (
        len(token) == 1 and unicodedata.category(token) in {'Mn', 'Mc', 'Me'}
    )
    return None, -0.00129 + (0.01 if broken_fragment else 0.0)

programs.sol:
"""Predict an unspaced continuation after an identifier separator.

Letters in the next token give a strong negative response after a dot,
especially a dot attached to other punctuation. Scope resolution, pointer
arrows, command-line dashes, and underscored names give weaker responses.
Repeated dots, capitals, and mixed-case subwords attenuate the response.
Whitespace and digits mostly suppress it; nonbreaking spaces are an exception.
Only the preceding token in the same document is retained. Individual word
values and longer-range context are deliberately not memorized.
"""
READS = ()

# Familiar identifier separators, ordered from longer to shorter suffixes.
SEPARATORS = (
    ("::", 1.12),
    ("->", 1.28),
    ("__", 0.22),
    (":", 0.24),
    ("_", 0.17),
    ("@", 0.17),
)


def boundary_strength(previous):
    if previous.endswith("."):
        if previous.endswith(".."):
            return 0.52
        return 1.72 if previous == "." else 2.2
    if previous.endswith("--"):
        if previous == " --":
            return 0.93
        return 0.7 if previous.endswith("'--") else 0.3
    if previous.endswith("_") and "." in previous:
        return 0.82
    if (len(previous) > 1 and previous[-2] == "."
            and (previous[-1].isalpha() or previous[-1] == "/")):
        return 0.4
    for separator, strength in SEPARATORS:
        if previous.endswith(separator):
            return strength
    return 0.0


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    token = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ""
    value = 0.0
    if token and previous:
        dot = previous.endswith(".")
        ellipsis = previous.endswith("..")
        first = token[0]
        if token == "\xa0":
            value = -0.65 if dot else -0.07
        elif first.isspace():
            if dot:
                value = 0.04 if previous == "." or ellipsis else 0.08
        elif first.isascii() and first.isalpha():
            scale = 1.0 if token.islower() else 0.8
            if not token.islower() and not token.istitle() and not token.isupper():
                scale = 0.73
            value = -boundary_strength(previous) * scale
        elif first.isascii() and first.isdigit():
            if dot:
                if ellipsis:
                    value = -0.22
                else:
                    value = -0.04 if previous == "." else -0.5
        elif first.isalpha() and dot and not ellipsis:
            value = -0.42
    return (doc, token), value

programs.luna:
"""Identify the boundary markers used around tool calls and replies.

The component is most negative at the end of an assistant tool call and
positive at the end of the tool's response. It also gives smaller signals
on adjacent message-boundary markers.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""

    if token == "</tool_call>":
        return None, -1.26
    if token == "</tool_response>":
        return None, 0.60
    if token == "<tool_response>":
        return None, -0.65
    if token == "<tool_call>":
        return None, -0.12
    if token == "<|im_end|>":
        if previous == "</tool_call>":
            return None, -0.47
        if previous == "</tool_response>":
            return None, -0.15
    if token == "<|im_start|>":
        return None, 0.14
    return None, 0.0

programs.sol:
"""Negative response to short -ate words, especially rate/late/gate.
Date, hate and plate are weaker; late also depends on case/word boundary.
Split -ate endings respond more after
short, consonant-heavy stems, and after chemical-salt stems; -ated/-ating
are weaker. Common rate modifiers and 'rate of' adjust the prediction.
Early, scale, -ate names and two Chinese rate/late characters are secondary
cues. All other tokens get zero.
Only the previous token is remembered, reset at document boundaries.
"""
import re
READS = ()
SALT_STEMS = ('acet', 'bor', 'carbon', 'chlor', 'citr', 'form',
              'lact', 'nitr', 'phosph', 'sulf')
FINANCE = {'tax', 'interest', 'exchange', 'inflation', 'discount', 'coupon'}
BIOLOGY = {'heart', 'metabolic', 'mortality', 'birth', 'death',
           'survival', 'infection'}


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    word = s.lstrip(' \t\r\n_-.(/').lower()
    prev = previous.strip().lower()
    value = 0.0
    if word in ('rate', 'rates', 'gate', 'fate', 'mate', 'crate'):
        value = -2.8
        if word in ('rate', 'rates') and s.startswith(' '):
            if prev == 'growth':
                value = -1.45
            elif prev in FINANCE or prev in BIOLOGY:
                value = -2.2
            elif prev in ('the', 'a', 'this', 'high', 'higher', 'average'):
                value = -3.5
        elif word in ('gate', 'crate') and not s.startswith(' '):
            value = -3.5
    elif word == 'late':
        value = -4.0 if s.startswith(' ') else -2.6
        if word == 'late' and s.lstrip()[:1].isupper():
            value = -4.6 if s.startswith(' ') else -3.85
    elif word in ('gates', 'fates', 'mates'):
        value = -2.4
    elif word in ('date', 'dates', 'early', 'graduate', 'alternate'):
        value = -0.9
    elif word in ('hate', 'hates', 'dating', 'dated', 'hated', 'rated', 'crates',
                  'gating'):
        value = -1.2
    elif word == 'gated':
        value = -2.2
    elif word in ('kate', 'nate', 'tate'):
        value = -1.6
    elif word in ('slate', 'skate'):
        value = -1.0
    elif word in ('plate', 'plates', 'scale'):
        value = -0.55
    elif word == 'rating':
        value = -0.85
    elif any(word == root + 'ate' for root in SALT_STEMS):
        value = -1.25
    elif word in ('ate', 'ates', 'ated', 'ating'):
        match = re.search('[A-Za-z]+$', previous)
        stem = match[0].lower() if match else ''
        n = min(len(stem), 8)
        vowels = sum(c in 'aeiou' for c in stem)
        if word == 'ate':
            value = -3.2 + .33*n - .15*max(0, n-4) + .34*vowels
        elif word == 'ates':
            value = -3.4 + .47*n - .5*max(0, n-4) + .52*vowels
        else:
            value = -.95 + .17*min(n, 4) + .12*vowels
            value -= .35 if word == 'ated' else 0.0
        if word in ('ate', 'ates') and any(stem.endswith(r) for r in SALT_STEMS):
            value -= 1.0 if word == 'ate' else .5
        if previous.isupper():
            value -= .45
        value = -1.5 if s.startswith(' ') else max(-4.5, min(.6, value))
    elif word in ('uate', 'iate', 'inate', 'imate'):
        value = -0.65
    elif s == '晚':  # Chinese: late/evening
        value = -1.65
    elif s == '率':  # Chinese: rate/ratio
        value = -0.65
    if s == ' of' and prev in ('rate', 'rates'):
        value = -1.1
    return (doc, s), float(value)

programs.luna:
"""Predict boundary-marker responses with a few familiar chat-format cues.

Message-start markers are strong positive responses; a start inside a document
differs from one at document start. Tool-response and reasoning
brackets also have characteristic positive responses, while message and tool
closers are mildly negative. Other text is predicted as zero.
"""
READS = ()

MARKER_RESPONSE = {
    "<tool_response>": 0.90,
    "<think>": 0.42,
    "</think>": 0.65,
    "</tool_call>": -0.08,
    "</tool_response>": -0.12,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    position = prefix.position
    within_document = (
        position > 0
        and prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    previous = prefix.token_strings[-2] if within_document else ""
    if token == "<|im_start|>":
        return None, 1.28 if within_document else 0.725
    if token == "<|im_end|>":
        end_value = {"</tool_response>": -0.19, "</tool_call>": -0.155}
        return None, float(end_value.get(previous, -0.13))
    return None, float(MARKER_RESPONSE.get(token, 0.0))

programs.sol:
"""Hands/fingers versus the short scope of before/while/without.

Recognize body-part names, their word pieces, and hand-held tools. Nearby
possessives and left/right modify the positive lexical response. Temporal and
negative linkers cause a negative response over the next three tokens,
especially on continuing states, participles and scope words. Lifecycle-hook
names are treated similarly. Scope fades and stops at sentence boundaries;
all state resets between documents. Selected scope words also get a small
negative background offset. These lexical heuristics do not resolve word meaning.
"""
READS = ()


def lexicon(groups):
    return {w: value for value, words in groups for w in words.split()}


BODY = lexicon([
    (4.4, 'finger fingers'), (3.5, 'thumb'),
    (2.5, 'fingertip fingertips'), (2.0, 'hand arm palm forearm pointer'),
    (1.7, 'wrist elbow fist fists'), (1.6, 'hands thumbs palms'),
    (1.3, 'arms wrists hammer gesture'), (1.0, 'shoulder ankle bracelet ptr paw'),
    (0.8, 'knee tongue sword gloves wand'),
    (0.65, 'foot nail nails needle needles spoon cursor touch grip tip rod '
           'glove thermometer'),
    (0.5, 'leg stick sticks knife knives pencil gun arrow brush staff'),
    (0.3, 'legs feet knees shoulders sleeve pen tips touching'),
    (1.1, 'handed handheld pointers'),
    (0.9, 'inger'), (1.8, 'ingers'), (1.7, 'fing'), (3.3, 'fingert'),
])
BODY.update({
    '手': 1.0, '指': 2.5, '腕': 1.7, '臂': 2.5, '掌': 1.5,
    '拳': 3.6, '腿': 1.5, '足': 0.75, '棒': 2.5, '棍': 2.5,
    '笔': 1.0, '筆': 1.0, '袖': 0.8, '针': 1.2, '針': 1.1,
    '手指': 4.6, '手掌': 3.8, '拇指': 3.2, '指尖': 3.6,
    '手臂': 2.9, '手腕': 2.6, '拳头': 2.5, '指甲': 1.4,
    '用手': 1.7, '的手': 1.8, '伸手': 1.5, '握': 1.5,
    '手势': 2.0, '挥手': 2.2, '戒指': 1.5, '筷子': 2.0,
})
SCOPE = lexicon([
    (4.2, 'having'), (3.8, 'being'),
    (3.0, 'maintaining'), (2.5, 'keeping preserving retaining becoming'),
    (2.0, 'using getting doing going coming leaving waiting trying considering '
          'providing requiring needing knowing continuing receiving'),
    (1.5, 'starting proceeding holding reading finishing completing applying '
          'causing affecting supporting visiting entering'),
    (1.2, 'making taking giving moving working'),
    (3.5, 'ever further long finally necessarily complete'), (2.5, 'first now'),
    (2.0, 'any more even other others not'), (1.0, 'all each every another only'),
])
CUES = {'before': 1.0, 'while': 1.0, 'without': 0.9, 'after': 0.4,
        'prior': 0.4, 'until': 0.3, 'when': 0.2, 'despite': 0.4,
        'during': 0.2, 'although': 0.15, 'except': 0.15}
# Common software lifecycle events also occur after before/after.
EVENTS = set('install request compile send show render call load save '
             'delete update disconnect each all'.split())
ARTICLES = {'a', 'an', 'the'}
POSSESSIVES = {'my', 'your', 'his', 'her', 'their', 'our'}
PRONOUNS = set('i you he she it they we us me him her them there'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, cue, age = '', '', 4
    else:
        previous, cue, age = carry[1:]
    token = prefix.token_strings[-1]
    clean = token.strip()
    word = clean.strip('_-.').lower()
    # Positive lexical response, with simple body-part context adjustments.
    value = BODY.get(word, 0.0)
    if clean[:1].isupper() and word not in {'finger', 'fingers', 'pointer', 'ptr'}:
        value *= 0.75
    if not token[:1].isspace() and word in {'arm', 'leg', 'foot', 'rod', 'pen'}:
        value *= 0.3
    if word == 'hand' and not clean.startswith('-'):
        if previous == 'other':
            value = 0.3
        elif previous in POSSESSIVES or previous in {'left', 'right'}:
            value += 1.0
    if word in {'arm', 'palm', 'thumb'} and previous in {'left', 'right'} | POSSESSIVES:
        value += 0.7
    if word == 'staff' and previous == 'magic':
        value += 0.6
    if word in {'still', 'having', 'further', 'least', 'otherwise', 'simply'}:
        value -= 0.2
    # Negative temporal scope, depending on the following word's grammatical role.
    strength = SCOPE.get(word, 0.25 if word.isalpha() else 0.0)
    if word not in SCOPE and (word.endswith('ing') or word.endswith('ly')):
        strength = 0.75
    if word in PRONOUNS or word in POSSESSIVES:
        strength = 0.5
    if word in ARTICLES:
        strength = 0.0
    if cue == 'while':
        if word in {'still', 'also'}:
            strength = 5.0
        elif word == 'simultaneously':
            strength = 3.5
        elif word in {'true', 'false'} or clean.lower().startswith(('(!', '(true')):
            strength = 2.8
        elif word == 'at':
            strength = 2.0
        elif word in {'in', 'on', 'under'}:
            strength = 1.1
    if cue == 'before':
        if word in {'first', 'long'}:
            strength = 3.9
        elif word == 'hand':
            strength = value + 2.2  # before + hand is not a bodily hand.
        elif word in EVENTS and (clean[:1].isupper() or clean.startswith('_')):
            strength = 2.8
    if cue == 'without' and word in {'regard', 'loss', 'doubt', 'exception'}:
        strength = 2.7
    if cue == 'prior' and word.isalpha() and word not in ARTICLES:
        strength = 2.1
    if cue and age < 3:
        value -= CUES[cue] * strength * (1.0, 0.5, 0.25)[age]
    # Update only causal, document-local state for the next token.
    age += 1
    if word == 'whilst':
        word = 'while'
    if word in {'beforeeach', 'beforeall'}:
        word = 'before'
    if word.rsplit('_', 1)[-1] in CUES:
        word = word.rsplit('_', 1)[-1]
    if word in CUES:
        cue, age = word, 0
    elif (clean and not any(c.isalnum() for c in clean)
          and any(c in '.?!;' for c in clean)):
        cue, age = '', 4
    return (doc, word, cue, age), float(value)

