# Hands, palms, wrists, arms, and hand compounds ("-hand", "-handed", "gloves").
HAND = {"hand", "hands", "palm", "palms", "wrist", "arm", "arms", "-hand", "-handed",
        "gloves", "glove", "手", "腕", "臂", "指"}
# Joints of the upper body and lower limb.
JOINT = {"elbow", "knee", "shoulder", "肘", "膝", "肩"}
# Other limbs and body parts: weak.
LIMB = {"leg", "legs", "foot", "feet", "toe", "toes", "neck", "eye", "ankle", "腿", "足", "脚"}
# Hand-held long objects: weak.
TOOL = {"stick", "staff", "rod", "needle", "wand", "hammer", "sword", "spoon", "棒", "棍", "剑", "笔"}
# Words that, placed before a hand or arm, say whose it is.
POSSESSIVE = {"my", "your", "his", "her", "their", "our", "its", "left", "right", "the", "a"}
# Words that open a subordinate clause; the word after them is a clause verb.
SUBORD = {"while", "before", "without", "prior", "despite", "whilst", "after"}


def step(carry, prefix, upstream):
