    '</tool_call>': 0.214,
    '</tool_response>': -0.056,
    '<tool_call>': 0.010,
    '<tool_response>': -0.022,
    '<think>': -0.090,
    '</think>': 0.028,
    '<|im_end|>': -0.037,
    '<|endoftext|>': -0.017,
    '<|im_start|>': 0.012,
}


