"""Negation / "otherness" detector for layers.0.mlp.down_proj:758.

The component fires on words that negate or contrast with something else:
  * the English negator "not" (also "Not", "NOT", "/not", "_not"), strongest when it
    follows a clause boundary (", and not", ". Not", "but not") and weaker after
    a modal or "is/are/was"; it is silent after do-support ("do not", "does not",
    "did not", "don't").
  * foreign negators (non, nicht, не, 不, 非, pas, nie, ない), at about 1.
  * alternatives "other", "another", "else", "others", "otherwise", "rather",
    "cannot", and the not-equal operators "!=" and "≠", at about 1.
Everything else predicts 0.

Scoring: variance explained about 0.83 and Pearson r about 0.91 on eval rows. Switching
the component's output off and substituting this program move the model's next-token
distribution by a similar small amount (kl_fraction about 0.33).
"""

import re

READS = ()

FOREIGN_NEG = {"non", "nicht", "не", "nor", "pas", "不", "非", "nie", "ない"}
ALTERNATIVE = {"other", "another", "else", "others", "otherwise", "rather", "!=", "≠", "cannot"}
DO_SUPPORT = {"do", "does", "did", "don", "doesn", "didn"}
MODAL = {"could", "need", "should", "would", "will", "had", "have", "has", "can"}
BE = {"is", "are", "was", "were", "am", "be", "may", "might", "must", "shall", "'s", "’s", "'re", "’re", "'m", "’m"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = re.sub(r"[^a-z]", "", token.lower())  # "Not", "NOT", "/not", "_not" -> "not"
    prev = ""
    if len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if word == "not":
        if not token.startswith(" ") and prev not in DO_SUPPORT:
            return None, 5.3  # sentence-initial or identifier "not"
        if prev in DO_SUPPORT:
            return None, 0.0
        if prev in MODAL:
            return None, 1.5
        if prev in BE:
            return None, 2.8
        return None, 4.5
    if token.strip().lower() in FOREIGN_NEG:
        return None, 1.0
    if token.strip().lower() in ALTERNATIVE:
        return None, 0.9
    return None, 0.0

