    "=>": -0.85, "⇒": -0.73,
    "指": -4.5, "表示": -3.2, "意味着": -6.1, "代表": -1.7, "意思": -3.0,
}
MEAN_FAMILY = {"mean", "means", "meaning", "meant", "meanings"}
# Words before which 'mean/means' is a noun ('the mean', 'by means of'), not a verb.
NOUN_CONTEXT = {"the", "a", "an", "of", "by", "and", "total", "sample", "population",
                "arithmetic", "other", "no", "any", "its", "their", "his", "her", "with",
                "find", "your", "my", "our", "better", "mere", "engaging", "all"}
# A subject that is a statement or thing ('This means', 'which means') boosts the verb.
STATEMENT_SUBJECTS = {"this", "that", "which", "it"}
NOUN_FACTOR = 0.3
SUBJECT_FACTOR = 1.3


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
