    # These isolated characters commonly signal incorrectly decoded UTF-8.
    damaged = any(c in ''.join(recent) for c in 'ÃÂï�')
    spaced = text.startswith(' ')
    value = 0.0
    if mark == '¡':
        if position == 0:
            value = -0.31
        elif previous == 'Å':  # Å¡ is a common broken rendering of š.
            value = -0.02
        elif previous == 'Ã' and not spaced:  # Ã¡ represents á.
            value = -0.07
        elif damaged:
            value = -0.02 if spaced else -0.15
        elif boundary:
            value = -0.48 if spaced else -0.54
        else:
            value = -0.27 if spaced else -0.15
    elif mark == '¿':
        if position == 0:
            value = -0.07
        elif damaged:
            value = -0.04 if spaced else -0.025
        elif boundary:
            value = -0.20 if spaced else -0.27
        else:
            value = -0.13 if spaced else -0.06
    elif mark == '„':
        if position == 0:
            value = -0.08 if spaced else -0.13
        elif previous in ('â', '�', 'Å'):
            value = 0.18 if spaced else 0.35
        elif '=' in ''.join(recent):  # A damaged glyph in an equation.
            value = 0.15
        elif damaged or 'â' in ''.join(recent):
            value = -0.07 if spaced else 0.25
        elif boundary:
            value = -0.16 if spaced else -0.20
        else:
            value = -0.09 if spaced else 0.06
    elif text == '.JsonIgnore':
        value = -0.19 if position == 0 else -0.51
    elif text == '<|im_start|>':
        value = 0.025 + 0.133 / (position + 1) ** 1.5
    elif text == '<think>':
        value = 0.105 if position == 0 else 0.145
    elif text in CHAT:
        value = CHAT[text]
    elif text in ('user', 'assistant') and recent and recent[-1] == '<|im_start|>':
        if position == 1:
            value = 0.10
        else:
            value = 0.015 if text == 'user' else -0.015
    # A few standalone writing/notation symbols, not substrings of words.
    elif mark == '@':
        value = 0.043 if spaced else 0.078
    elif mark == '_':
        value = -0.036 if spaced else 0.026
    elif mark == '~':
        value = -0.08
    elif mark == '%':
        value = -0.024
    elif mark == '$':
        value = -0.035 if spaced else -0.009
    elif mark in ('/', '\\'):
        value = 0.004 if spaced else 0.015
    elif mark == '··':
        value = -0.068
    elif mark == '«':
        if previous == 'Â':
            value = 0.025
        else:
            value = -0.045 if spaced else -0.12
    # At a document reset, these tokens denote layout or explicit headers.
    if position == 0:
        if text == ' ':
            value = -0.091
        elif text == '  ':
            value = -0.055
        elif text.strip() == '' and '\n' in text:
            value = -0.028 if text.count('\n') == 1 else -0.010
        elif mark in ('(', '[', '{'):
            value = 0.065 if spaced else 0.085
        elif text == 'package':
            value = 0.147
        elif text in ('Title', 'Question'):
            value = 0.10
        elif mark in ('#', '##', '###'):
            value = 0.08 * len(mark) - 0.092
    return (doc, position + 1, (*recent[-2:], text)), value

"""Respond to nine in digits, English words, Chinese, and September.

A 9 is strongest after a digit other than 9; fullwidth digits use the
same rule. The preceding digits have different calibrated strengths.
A decimal point also strengthens the response. English and Chinese
numeral forms have separate strengths. September, the ninth month,
is strongest after a day number. Other tokens receive zero: their
small token-specific background responses are omitted.
"""

READS = ()

# Strength of a 9 immediately following each digit, from zero to nine.
AFTER_DIGIT = (1.42, 1.97, 2.06, 1.68, 1.60,
               1.83, 2.02, 1.83, 1.65, 0.88)
CHINESE_DIGITS = frozenset('零〇一二三四五六七八九十')
WIDTH_TO_ASCII = str.maketrans('０１２３４５６７８９', '0123456789')
DIGITS = frozenset('0123456789')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    digit = previous.translate(WIDTH_TO_ASCII)
    digit = digit if digit in DIGITS else None
    value = 0.0

    if token in ('9', '９'):
        if first:
            value = 0.19
        elif digit is not None:
            value = AFTER_DIGIT[int(digit)]
        elif previous == '.':
            value = 1.01
        elif previous in (',', '/'):
            value = 0.83
        elif previous == '\\x':
            value = 0.22  # a hexadecimal escape, not a decimal number
        elif previous.isspace():
            value = 0.55
        else:
            value = 0.60
    elif word == 'nine':
        value = 0.46
    elif word == '-nine':
        value = 1.65
    elif word == 'ninety':
        value = 1.05 if previous.strip().lower() == 'and' else 0.88
    elif word in ('nineteen', 'ninth'):
        value = 0.66
    elif token in ('九', '九年', '九月'):
        value = 1.62 if previous and previous[-1] in CHINESE_DIGITS else 0.55
    elif token == '十九':
        numeral_before = previous and previous[-1] in CHINESE_DIGITS - {'九'}
        value = 2.45 if numeral_before else 1.55
    elif token == '第九':
        value = 1.45
    elif word in ('september', 'sep'):
        if digit is not None:
            value = 0.35 * AFTER_DIGIT[int(digit)]
        elif previous.strip().lower() == 'on':
            value = 0.01
        else:
            value = 0.18
    return (doc, token), float(value)

programs.haiku:
"""Layer-0 MLP unit 763 (down_proj): a word detector for a few families of nouns.
It goes negative (and only negative) on:
  1. Greek/Latin technical plurals and their kin: criteria, phenomena, genera, taxa,
     spectra, bacteria, media, eigen, larvae, algae, fungi, stimuli, nuclei, dice, alumni;
  2. the scientific "spec-" words: species, specimen, spectrum, spectral, spect, spec;
  3. living things and what they cause or are made of: fish, sheep, mice, cattle,
     livestock, insects, salmon, trout, shrimp, organisms, creatures, offspring, yeast,
     bacterial, microbial, influenza, malaria, fungal, flora, fauna;
  4. equipment, vehicles and troops: aircraft, -craft words, equipment, apparatus,
     personnel, furniture, premises, firearms, cavalry, artillery, infantry, militia.
  5. 'of' right after 'species' or 'genus'.
Everything else is 0. The value depends on the current word only (and the one before
for 'of'), so it is a lookup of these word families."""

READS = ()

TECHNICAL = {
    "criteria": -4.3, "criterion": -1.3, "phenomena": -1.4, "phenomenon": -0.35,
    "genera": -1.2, "genus": -0.6, "taxa": -1.8, "spectra": -2.3, "spectrum": -0.5,
    "bacteria": -1.9, "media": -1.0, "eigen": -1.5, "larvae": -1.4, "algae": -1.7,
    "fungi": -2.0, "stimuli": -1.5, "nuclei": -0.9, "dice": -1.3, "alumni": -0.8,
    "axes": -0.5, "hypotheses": -0.5,
}
SPEC = {"species": -2.5, "specimen": -0.9, "specimens": -1.0, "spectral": -0.7,
        "spect": -0.7, "spec": -0.5, "spectro": -0.7}
LIVING = {
    "fish": -1.0, "sheep": -1.2, "mice": -1.0, "cattle": -1.0, "livestock": -1.2,
    "insects": -0.5, "salmon": -0.7, "trout": -0.8, "shrimp": -0.5, "tuna": -0.5,
    "organisms": -0.6, "organism": -0.4, "creatures": -0.6, "creature": -0.5,
    "offspring": -1.4, "yeast": -0.7, "bacterial": -0.5, "microbial": -0.4,
    "influenza": -0.8, "malaria": -0.7, "fungal": -0.8, "flora": -0.7, "fauna": -0.6,
    "deer": -0.5, "wildlife": -0.6, "fisheries": -0.8, "predator": -0.6, "prey": -0.7,
}
MILITARY_EQUIPMENT = {
    "aircraft": -2.3, "equipment": -0.6, "apparatus": -0.6, "personnel": -0.55,
    "furniture": -0.8, "premises": -0.7, "firearms": -0.6, "cavalry": -0.5,
    "artillery": -0.5, "infantry": -0.35, "militia": -0.65, "troops": -0.3,
}
VALUES = {**TECHNICAL, **SPEC, **LIVING, **MILITARY_EQUIPMENT}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower().strip("./-_()")
    value = VALUES.get(word, 0.0)
    if value == 0.0 and word.endswith("craft"):
        value = -1.5
    if word == "of" and len(prefix.token_strings) > 1:
        if prefix.token_strings[-2].strip().lower() in ("species", "genus"):
            value = -0.7
    return carry, float(value)

programs.sol:
"""Approximate a negative response to unexpectedly joined capitals.

Title-shaped fragments after lowercase endings, digits, closing brackets,
or sentence punctuation receive negative values. Spaced title words are
usually near zero. Recent braces, assignments, underscores and escapes
weaken the lowercase-to-capital response. Some short joined name fragments
get stronger values than long ones. There are separate document-initial and
chat-marker rules. Category means are modestly amplified to emphasize
their downstream effect.
This captures boundary/case patterns, not all token-specific variation.
"""
import re

READS = ()
CODE_PUNCTUATION = frozenset('{}[]=;_\\')


def response(token, previous, start, code):
    word = token.strip()
    prior = previous.strip()
    prior_letters = sum(c.isalpha() for c in prior)
    spaced = bool(token) and token[0].isspace()
    if re.match(r'^[.!?,:;]+[A-Z]', word):
        if code > 0.1:
            return -0.033
        if prior_letters <= 4:
            return -0.178
        return -0.704 if previous[0].isspace() else -0.117
    if not word.istitle():
        return 0.0004
    if start:
        if sum(c.isalpha() for c in word) <= 2:
            return -0.026
        return 0.013 if spaced else -0.328
    if spaced:
        return 0.0
    last = previous[-1:] if previous else ''
    if last.islower():
        if code > 0.1:
            return -0.064 if prior.isalpha() else 0.007
        if not word[0].isupper():
            return -0.019
        if previous[0].isspace():
            if not prior.istitle():
                return -0.215
            if prior_letters <= 2:
                return -0.188
            return -0.502 if sum(c.isalpha() for c in word) <= 5 else -0.323
        return -0.227 if prior.isalpha() else -0.066
    if last in ('.', '!', '?'):
        return -0.497
    if prior.isdigit():
        return -0.107 if word.isupper() else -0.356
    if last in (')', ']', '}'):
        return -0.296
    return 0.014


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    # Attention and this small history both restart at document boundaries.
    previous, code = ('', 0.0) if start else carry[1:]
    token = prefix.token_strings[-1]
    value = response(token, previous, start, code)
    # A chat header is another special boundary rather than ordinary prose.
    if previous == '<|im_start|>':
        if token == 'assistant':
            value = -0.247
        elif token == 'user':
            value = 0.061
    elif token == '<|im_start|>':
        value = 0.026
    if token == '</think>':
        value = 0.039
    code = 0.8 * code + sum(c in CODE_PUNCTUATION for c in token)
    return (doc, token, code), float(1.25 * value)

"""A lexical signal for the attribute being specified in a noun phrase.

The listed quantity and property names are negative, especially after 'the' or a
possessive. Size and length are strongest. Identifiers and plurals are weaker.
The next 'of' continues the phrase; 'a number of' instead has a positive offset.
The small word groups below give ordinary and definite-phrase amplitudes.
"""
READS = ()

GROUPS = (
    (-1.23, -2.17, 'size'),
    (-1.10, -1.60, 'length magnitude severity'),
    (-0.59, -1.42, 'amount'),
    (-0.57, -1.21, 'number'),
    (-0.18, -1.20, 'extent'),
    (-0.45, -1.35, 'nature'),
    (-0.50, -0.90, 'accuracy validity duration thickness breadth wavelength '
                       'rate quality frequency strength intensity effectiveness '
                       'availability prevalence timing'),
    (-0.39, -0.70, 'volume cost quantity direction incidence value width price '
                       'scope reliability existence'),
    (-0.27, -0.66, 'location structure shape composition speed depth status'),
    (-0.28, -0.46, 'distance height density temperature success'),
    (-0.16, -0.32, 'age weight performance design color date efficiency velocity '
                       'radius diameter dimensions style probability ratio growth '
                       'scale'),
    (-0.10, -0.80, 'type degree'),
    (-0.03, -0.46, 'level use'),
    (-0.10, -0.67, 'importance presence'),
    (-0.06, -0.35, 'purpose role name position lack'),
)
PROPERTIES = {w: (ordinary, definite)
              for ordinary, definite, words in GROUPS for w in words.split()}
POSSESSIVES = set('its their his her our your whose'.split())


def of_signal(word, value):
    if word == 'number':
        return 0.68 * value + 0.52
    if word == 'amount':
        return 0.78 * value + 0.27
    if word == 'value':
        return 0.65 * value + 0.22
    if word == 'nature':
        return 0.50 * value - 0.40
    if word in {'accuracy', 'importance', 'use', 'presence', 'weight'}:
        return 0.20 * value
    if word in {'shape', 'structure', 'direction', 'location', 'status'}:
        return 0.90 * value
    return (0.48 if word == 'length' else 0.60) * value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, following_of = '', 0.0
    if carry is not None and carry[0] == doc:
        _, previous, following_of = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    spelling = 1.0 if token[:1].isspace() else 0.70
    if word.startswith(('.', '_', '-')):
        spelling = 0.52
        word = word[1:]
    root = word[:-1] if word.endswith('s') and word not in PROPERTIES else word
    value, next_of = 0.0, 0.0
    if root in PROPERTIES:
        ordinary, definite = PROPERTIES[root]
        if previous == 'the':
            value = definite
        elif previous in POSSESSIVES:
            value = 0.65 * definite + 0.35 * ordinary
        else:
            value = ordinary
        if previous in {'a', 'an', 'some', 'any'}:
            value *= 0.70 if root in {'size', 'length', 'number', 'width'} else 0.45
        if root != word:
            value *= {'numbers': 0.4, 'amounts': 0.65}.get(word, 0.75)
        value *= spelling
        next_of = of_signal(root, value)
    elif word in {'大小', '长度'}:
        value = -1.10
    elif word in {'размер', 'tamaño', 'tamanho', 'taille', '大き'}:
        value = -0.95
    elif word in {'数量', '金额'}:
        value = -0.75
    elif word in {'长', '長', '速度', '的速度', '质量', 'качество'}:
        value = -0.40
    elif word in {'ness', 'eness', 'iness', 'iveness'}:
        value = -0.35
    elif word in {'large', 'larger', 'largest', 'small', 'smaller', 'smallest'}:
        value = -0.18
    elif word == 'exact':
        value = -0.43
    elif word == 'of':
        value = following_of
    return (doc, word, next_of), float(value)

"""Approximate a signed lexical response: toppling versus security/precision.

The largest negative cue is 倒 (fall over, invert, or pour). Related
Chinese opposition/tilting words and English pouring, disposal, throwing,
and inversion words give smaller negatives. 'pour' fires in French too:
this is a token-level lexical response, not a contextual sense classifier.
Security, precision, selected scientific/medical terms, and the code
word 'module' give positive responses.
The fragments 'recision' and 'verted' also count as lexical cues.
Other tokens get zero; document history and word senses are not modeled.
"""
READS = ()

# Exact tokens matter: longer compounds often have a weaker response.
TOPPLING_AND_CONTRAST = {
    '倒': -7.15, '倒是': -3.13,
    '倾': -1.43, '傾': -1.43, '歪': -0.90, '斜': -0.52,
    '反': -0.82, '反而': -1.32,
    '却': -0.65, '卻': -0.65, '而是': -0.46,
    '浇水': -0.74, '斟': -1.48,
}


QUALITY_AND_SAFETY = {
    '安全': 0.32, '精': 0.52, '精度': 0.44, '监控': 0.54,
    '科学': 0.49, '专业': 0.39, '医药': 1.07,
    'sécurité': 0.34, 'securities': 0.41,
    'health': 0.14, 'science': 0.22,
    'protection': 0.22, 'safety': 0.15,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in TOPPLING_AND_CONTRAST:
        return None, TOPPLING_AND_CONTRAST[token]
    word = token.strip().lstrip('._/-(')
    lower = word.lower()
    if word in QUALITY_AND_SAFETY:
        value = QUALITY_AND_SAFETY[word]
    elif lower == 'security':
        value = 0.52
        if token == ' security':
            value = 1.03
        elif token == '.Security':
            value = 0.45
        elif word == 'Security':
            value = 0.81
        elif word == 'SECURITY':
            value = 0.42
    elif word == 'recision':
        value = 0.64
    elif lower == 'precision':
        if word != 'precision':
            value = 0.56
        else:
            value = 0.70 if token.startswith(' ') else 0.90
    elif lower == 'module':
        value = 0.71 if token == 'module' else 0.24
    elif lower in ('pour', 'pours', 'poured', 'pouring'):
        value = -0.55 if lower == 'pour' else -0.47
    elif lower in ('dispose', 'disposed'):
        value = -0.90
    elif lower in ('disposing', 'disposable'):
        value = -0.55
    elif lower == 'inverted':
        value = -0.99
    elif lower == 'verted':
        value = -0.63
    elif lower in ('invert', 'reverse'):
        value = -0.33
    elif lower in ('throw', 'throws', 'thrown'):
        value = -0.33
    elif lower == 'throwing':
        value = -0.14
    elif lower in ('lean', 'leaned', 'leaning'):
        value = -0.15
        if token.startswith(' '):
            value = -0.41 if word.islower() else -0.22
    elif lower in ('tilt', 'tilted'):
        value = -0.30
    elif lower == 'sprawling':
